WordHunterWoW_QuestEN[74334] = { title = "Future Aspects", description = "My brothers are not interested in investigating the Sundered Flame or helping Emberthal. \n\nIt worries me that we are dividing our efforts, but I understand their motivation in considering our next steps against Fyrakk immediately.\n\nI will aid Emberthal as I promised, but perhaps we should ask for help from the local niffen...", objectives = "Suggest Honeypelt as a guide.", completion = "Thank you for continuing to aid us, <name>. Emberthal will fill you in on what we have discovered so far." }
WordHunterWoW_QuestEN[74335] = { title = "A Moment of Reflection", description = "I do not understand what would drive Turi Flickerflame and her band of mages to attempt what they have done here today. But I do understand the pain of losing family. I understand the fear and regret that follows you wherever you go.\n\nI have much to think about. I imagine Kalecgos has much yet to do in the Dragon Isles--return there with him. I will follow soon... I need some time to think upon what happened here today.", objectives = "Return to Kalecgos in the Azure Span.", progress = "Welcome back, <name>.", completion = "Surigosa and Azuregos are hardly the only members of my flight to question my more measured approach to the misuse of magic. I'm glad for their perspectives--and their willingness to check my optimism.\n\nStill, I hope that they will come to see things as I do now.\n\nCome. We have much yet to do." }
