WordHunterWoW_QuestEN[74433] = { title = "Returning the Blade", description = "<This dagger, found buried in the chest of the giant worm Icebreaker, belonged to Saza. It is evident that Saza fought bravely, deeply wounding the monster before her death.\n\nThis blade should be brought back to the village to give her clan closure.>", objectives = "Bring Saza's dagger to the Winterpelt.", progress = "That's... Saza's dagger. Why do you have her dagger? Oh...", completion = "<Jyrra sighs as you tell her the news, her eyes dulled by tears.>\n\nThank you for bringing this dagger back and for telling us of her bravery. Saza fought hard for her family. As I would too.\n\nI should have gone with you. If only...\n\nI'm sorry, <name>. I am in your debt. \n\n\n\nOh, I will miss you, little sister..." }
WordHunterWoW_QuestEN[74436] = { title = "Storm Warning", description = "Ah, {class}! I knew I would find you at the right place at the right time. \n\nThe elements do not just threaten the Dragon Isles in our current time, but also from beyond. Go to the Temporal Conflux and travel through the rift into the future the primalists have overrun.\n\nThere, speak to Soridormi. She will have more details for you when you arrive.", objectives = "Speak to Soridormi in the Primalist Future. The portal to the Primalist Future can be found at the Temporal Conflux in Thaldraszus.", progress = "It is good to see you again.", completion = "We meet again, <name>. We have more need for your help, I'm afraid." }
WordHunterWoW_QuestEN[74437] = { title = "Resisting the Storm", description = "The Primalists are growing in strength in this future timeline, despite our best efforts. If they overrun this valley and threaten the Temporal Conflux, they may become a problem for the rest of the timeways.\n\nWe are already protecting the timeways from enough threats.\n\nPush back on them, {name}. We need to keep this peril in check. Speak to Tarnormu to gather any supplies you might need.", objectives = "Stock up on any necessary supplies and complete \"The Storm's Fury\" event in the Primalist Future.", progress = "We cannot let the Primalists become a threat to other periods in our history.", completion = "You have been an inspiration to the few forces that still remain, <class>. \n\nThe threat may be pushed back a little for now, but we must continue our vigil here so that the rest of the timeways are not in yet more dangers than before." }
WordHunterWoW_QuestEN[74440] = { title = "Windseeker Avash", description = "", objectives = "" }
WordHunterWoW_QuestEN[74441] = { title = "Eaglemaster Niraak", description = "", objectives = "" }
WordHunterWoW_QuestEN[74442] = { title = "One Dragon's Junk...", description = "Greetings! I am looking for items of power from my flight's past. \n\nWe have a history of great warriors and battle prowess, and I want to recover items that will help us reach that again.\n\nI heard you found these vaults. If you see anything of interest inside, could you show it to me?", objectives = "Locate an object for Voraxian within the Zskera Vaults.", progress = "Did you find anything interesting?", completion = "Oh, this is... definitely something?\n\nIt does not seem like it could be used as a weapon, but I suppose it is worth investigating. You never know." }
WordHunterWoW_QuestEN[74443] = { title = "Is Another Dragon's Treasure?", description = "I must admit, I am out of my depth here. \n\nIt is of black dragon make. The decoration on the pommel matches, but I have no idea what it is. Which I suppose is the point.\n\nI have heard you have travelled the Isles. Do you have any recommendations on who to talk to?", objectives = "Talk to Voraxian in the Forbidden Reach.", progress = "It is a fascinating object. I am tempted to tell Evorian it's a weapon just to see what happens when he tries to use it... but I suppose not. It might actually be really dangerous.\n\nWould be fun to see his scales singed a bit though.", completion = "You think this Veritistrasz could help? I am willing to give it a shot!\n\nGood suggestion, <name>." }
WordHunterWoW_QuestEN[74444] = { title = "Forbidden Reach 1/3 C and D", description = "", objectives = "" }
WordHunterWoW_QuestEN[74445] = { title = "Forbidden Reach 1/1 C and D", description = "", objectives = "" }
WordHunterWoW_QuestEN[74447] = { title = "Verbal Archaeology", description = "Where should we meet this Veritistrasz of yours?\n\nRuby Lifeshrine? Are you sure this is not an attempt to introduce me to Alexstrasza? \n\nNo? Well then! I shall meet you at the Ruby Lifeshrine!", objectives = "Talk to Veritistrasz.", progress = "Let us hope this is something exciting!", completion = "Well, that is a bit of a disappointment.\n\nI suppose an old egg-tending device is some form of culture, even if it is not very exciting. \n\nIf you find something else of interest in the vaults, I would be interested in looking at it." }
