WordHunterWoW_QuestEN[74476] = { title = "Slime Dies When You're Having Fun", description = "The investigators here told me that there were some side effects to removing the time anomaly from Eon's Fringe. Seems a bunch of slimes snuck through the timestream in the process. \n\nOh! Oh! Time slimes! They're time slimes! Ha.\n\nAnyway, could you take some of them out?", objectives = "Kill 12 Time Slimes.", completion = "I recorded the sounds of you killing the slimes for reference. I hope that's okay." }
WordHunterWoW_QuestEN[74488] = { title = "Runaway Rusziona", description = "Black whelps have the agility of a rock, but they try to make up for it with the most impressive top speed. Try to take it easy around those corners!\n\n[Eruption]: Dash forward.\n[Rock Halt]: Stops forward movement.\n[Earthen Will]: Restores all Vigor. Must be grounded.", objectives = "Help Rusziona glide through the rings.", progress = "How is the racing going?", completion = "Well done!" }
WordHunterWoW_QuestEN[74489] = { title = "Zhoomsa", description = "Bronze whelps can be careless when trying to win, so be careful with the timeways!\n\n[Growth Spurt]: Transform into an adult and gain improved speed.\n[Bedtime Rewind]: Restore 1 Vigor until all Vigor has been recovered.\n[Sacred Timeline]: Resets cooldowns.", objectives = "Help Zhusadormu glide through the rings.", progress = "How is the racing going?", completion = "Well done!" }
WordHunterWoW_QuestEN[74490] = { title = "Zaleth on the Go", description = "Blue whelps will try to skip ahead where they can, but be careful blinking through rings!\n\n[Blink Boost]: Blink forward and dash.\n[Arcane Acceleration]: Increases forward acceleration.\n[Accelerated Restoration]: Consumes Arcane Acceleration and restores Vigor.", objectives = "Help Zalthgos glide through the rings.", progress = "How is the racing going?", completion = "Well done!" }
WordHunterWoW_QuestEN[74491] = { title = "Pole Position Posidriss", description = "Green whelps have an affinity for short naps and bursts of speed, so do your best to keep pace.\n\n[Nature's Wind]: Fly up then restore 1 Vigor.\n[Emerald Restraint]: Adds 5 sec to Winds of Life's duration.\n[Winds of Life]: Anytime you restore Vigor, dash forward.", objectives = "Help Posidriss glide through the rings.", progress = "How is the racing going?", completion = "Well done!" }
WordHunterWoW_QuestEN[74492] = { title = "Blistering Belastrasza", description = "Red whelps can be a little out of control, so best of luck!\n\n[Ruby Exhaustion]: Consumes all Vigor over time.\n[Crimson Flight]: Restore all Vigor, boosting forward each time.\n[Renewal]: Consumes Crimson Flight, resets cooldowns.", objectives = "Help Belastrasza glide through the rings.", progress = "How is the racing going?", completion = "Well done!" }
WordHunterWoW_QuestEN[74493] = { title = "Second Time Is The Charm", description = "<Voraxian bounces the Odd Round Object in his hands a few times.>\n\nHmm, it lands in the hand well, like it was made for this. Let us talk to Veritistrasz and see if he knows more.", objectives = "Determine the origin of the Odd Round Object.", progress = "Let us hope it is something exciting this time!", completion = "By the Titans... talk about putting my claw in my jaw. \n\nSorry <name>, I will sit here for a bit with Veritistrasz and wait until he is ready to talk again. \n\nIf you find anything else of interest, please do bring it along." }
WordHunterWoW_QuestEN[74494] = { title = "A Scale for a Scale", description = "The elder waking was a threat, certainly. But there is one more mission I must complete before we depart, lest we lose our only chance to complete it at all.\n\nHowever different the Zaqali tribe may be from the Qalashi, they are still dragonslayers. Their implements of war are no less deadly to our kind.\n\nI need a spear on par with the one we saw at the elder's side. Find the largest one you can and deliver it to me.", objectives = "Collect a Zaqali Dragonslayer's Spear for Sabellian.", progress = "Djaradin weapons are vile creations, but they were created for one task and one task alone.", completion = "This is the only way forward." }
WordHunterWoW_QuestEN[74495] = { title = "The Tale of Hraxian", description = "Hello {name}, it is good to see you.\n\nWould you like to join us around the fire? I think it is time we heard a positive story about the obsidian flight of old.\n\nI once promised yourself and Voraxian I would tell you the story from the vase you found in the Zskera Vaults. I believe it is that time.", objectives = "Listen to the tale of Hraxian.", progress = "It is always a pleasure, <name>.", completion = "<Veritistrasz sits in silence for a short while.>\n\nThank you for listening, <name>. I have forgotten much over my life, but not this. \n\nI hope Hraxian's story gives the obsidian flight hope after the discoveries we made here." }
