WordHunterWoW_QuestEN[74514] = { title = "The Slowest Fan Club", description = "Has a crowd ever roared for you? Everyone shouting your name, pushing you on to victory? \n\nI want to give that same feeling to Slick. Give him the taste of being a champion.\n\nCourse, we don't speak snail, so we can only be so useful. Round up some snails that could use purpose in their lives. Slick needs a fan club.", objectives = "Collect 8 Aimless Snails.", progress = "A race track ain't no race track without fans to watch the race. That's just facts.", completion = "Perfect! Stick some Big Slick in the City merchandise on these critters and they're ready to go. Our boy's going to be more motivated than ever." }
WordHunterWoW_QuestEN[74515] = { title = "Snail Mail", description = "Racing snails are all about speed, but riding snails? They need stamina to boot.\n\nI owe some supplies to a buddy in Loamm. Why don't you make the delivery for me? Help build Slick's endurance.\n\nOh, and make sure you don't dismount. Not much of a training session if you keep hopping off and on.", objectives = "Deliver the package to Terryn in Loamm without dismounting Slick. If you get dismounted from Slick, Briggul can give you a new delivery.", progress = "This buddy of mine, always asking for supplies. I got snails to train!", completion = "Speed and stamina! This snail has it all, folks. Well done." }
WordHunterWoW_QuestEN[74516] = { title = "A Snail's Pace", description = "It's an off day for our local racing track, so I figured we could take the opportunity to build up Slick's speed. Grow some confidence on his home turf, I'm thinking.\n\nTake two laps around the track. Let's see how your training is coming along!", objectives = "Collect 1 Lap Markers by doing two laps around the snail track.", progress = "Not every day needs to be at a hundred, you know? Even in the fast-paced world of snail racing.", completion = "Look at you two, tighter than mucus brothers. Oh, that's what I call it when two snails get stuck to each other. Happens.\n\nYou're both coming along just fine. Can't wait to see where you go!" }
WordHunterWoW_QuestEN[74517] = { title = "All Terrain Snail", description = "While life in these caverns is plenty exciting, Slick has a future in the world above. Namely as your trusty mount. \n\nWhich means he needs to prepare for all sorts of environments.\n\nLuckily, the Dragon Isles has biomes to spare. Why don't you take him for a spin? Give him a taste of what's to come. One lap per location should do the trick.", objectives = "Ride Slick through Snail Markers in Restless Wetlands, Wanderer's Steppe, Upper Frostlands, and Shifting Sands.", progress = "I don't do too well above ground, myself. All that sunlight and fresh air just plays havoc on my sinuses.", completion = "Here comes Slick, traveler extraordinaire! Mucus seems alright, membranes nice and translucent, no cracks in the shell. \n\nThanks for taking care of him." }
WordHunterWoW_QuestEN[74518] = { title = "Resistance Training", description = "These caverns aren't easy on my poor snails, which is why I feed them a special crystal diet. Keeps their shells hard and gleaming. \n\nSlick eats more than his fair share though, so I'm plumb out. \n\nWould you collect some crystals in Zaralek Cavern? Get a nice mix, too. We need to make sure Slicks ready for every environment.", objectives = "Collect 5 Glowing Crystals, 5 Sulfuric Crystals, and 5 Magma Crystals from around Zaralek Cavern.", progress = "Everyone says they want their snails to have strong, healthy shells, but when it comes time to collect the crystals? They're too busy, they're too scared. \n\nCrokin' cowards..", completion = "That's the stuff! Just wait until you see how Slick's shell shines. Huh. Say that three times fast, am I right?" }
WordHunterWoW_QuestEN[74519] = { title = "Good for Goo", description = "Every snail trainer knows that it's all about the goo. The slime. The mucus. That's how you turn a speedy snail into a champion.\n\nSlick could use a good slather. Go out and collect some goo from the local slime trails to slick him up. Heh.", objectives = "Collect Goo from slimes and oozes in Zaralek Cavern.", completion = "Now that's a slicked Slick if I ever did see one. Nice job." }
WordHunterWoW_QuestEN[74520] = { title = "Less Cargo", description = "Those djaradin think they own these caverns, coming around here and looting our supplies. How am I supposed to train champions under these conditions?\n\nCan you do me a favor and get those supplies back? I can't help you train Slick without them. \n\nBesides, the big fellow could use a rest day.", objectives = "Collect 10 Stolen Supplies from djaradin in Igira's Watch.", progress = "Shell polish, mucus paste, racing rocks... Crok it all, we need those supplies back!", completion = "Shell yeah! Way to put the work in. Now we can get back to Slick's training." }
WordHunterWoW_QuestEN[74521] = { title = "A Flame, Extinguished", description = "Sarkareth is no more.\n\nHis hubris left him vulnerable to the dark influences that have assaulted our flight for millennia. Just like Neltharion before him.\n\nI believe Emberthal seeks more answers than what Wrathion and Sabellian are able to give. She may need some assistance.", objectives = "Speak to Wrathion or Sabellian.", progress = "Return to me if you'd like to help further.", completion = "Here we are, <name>.\n\nI admit that the black dragonflight's legacy is rife with moments that many would deem disreputable, vicious, or even vile.\n\nSo understand the weight of my words when I say that the contents of this edifice may be the worst of it." }
WordHunterWoW_QuestEN[74522] = { title = "Remnants", description = "Some call me a miracle, you know. Yet my birth was anything but natural. I was crafted, much as the creatures in here were crafted. Many died painful, tragic deaths so that I could live.\n\nThis... callousness towards the living is something I wish to eradicate.\n\nTake this, and use it to destroy any intact specimen tanks we encounter. Nothing deserves to suffer like this.", objectives = "Destroy 7 Specimen Tanks with the Blacktalon Napalm.", progress = "We need to end this here.", completion = "Finally, the suffering of these abominations has come to an end." }
WordHunterWoW_QuestEN[74523] = { title = "A Traitor's Due", description = "These sycophants shame themselves and the black dragonflight. It is clear that they are willing to die in service of my father's dark machinations.\n\nLet us not disappoint them.", objectives = "Defeat the Neltharion Loyalists.", progress = "We will never erase this mark on our legacy. But there is no way forward while they yet live.", completion = "Wrathion's Blacktalon may not be front-line soldiers, but they should be able to take care of the rest." }
WordHunterWoW_QuestEN[74525] = { title = "Honorbound", description = "<The djaradin's body is gaunt and wasted, its life energy siphoned away by the hungry machines that power this dark laboratory.\n\nPerhaps there are other djaradin imprisoned here that can be spared from this horror.>", objectives = "Free the imprisoned djaradin.", progress = "The black dragonflight is defined by our actions, not our accomplishments.", completion = "May they find the honor in death that was denied them in life." }
WordHunterWoW_QuestEN[74526] = { title = "Secured Shipment Looted", description = "", objectives = "" }
