WordHunterWoW_QuestEN[74529] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[74538] = { title = "Blow It Up", description = "Make no mistake, the djaradin are experienced dragon killers. But right now their ruthless tactics are overshadowed by the devastating power of their battlefield ballistae, capable of taking out any threat from a long distance. \n\nI have lost many good soldiers to these potent weapons.\n\nIt is essential that we destroy the ballistae if we hope to level the playing field and take to the skies. It is possible that we may even be able to gain the upper hand in this war.", objectives = "Destroy the djaradin heavy weaponry in the Battlefield Ruins.", completion = "We can see the smoke from up here! Good job." }
WordHunterWoW_QuestEN[74539] = { title = "Thinning Their Defenses", description = "The Firecallers are a formidable force. Their powerful, lethal magic allows them to vaporize anything that comes near them.\n\nTheir strategic positioning on high ledges makes them difficult to reach, but we cannot allow them to continue causing destruction among our forces.\n\nThe fate of our forces depends on your success. Good luck!", objectives = "Neutralize Zaqali Flametongues in the Battlefield Ruins.", progress = "Yes?", completion = "Another advantage taken from the enemy!" }
WordHunterWoW_QuestEN[74540] = { title = "Intercepting Communications", description = "{name}, we need intel, and we need it now.\n\nSomewhere within one of the djaradin's encampments, you will find their field general. He is a seasoned and formidable opponent, responsible for many attacks on our forces. \n\nAccording to our field agents, he may possess crucial military orders outlining their next offense and the locations of their new supply lines.\n\nIt is imperative that we obtain these orders. We cannot allow the djaradin to gain the upper hand.", objectives = "Eliminate Warchanter Ronvath and obtain the Invasion Plans in the Battlefield Ruins.", progress = "Report!", completion = "This is not what I expected, soldier.\n\nAccording to this report, the djaradin discovered a new dragon-like species living in the caves to the east.\n\n<Ignax puts his finger on the map.>\n\nThey also marked it as one of their assault points." }
WordHunterWoW_QuestEN[74542] = { title = "Air Superiority", description = "<As Ignax looks up, you see a small smile appear on his face.>\n\nFew of my soldiers have experience fighting alongside dragons. What a glorious day.\n\nTheir presence gives us confidence, {class}. Now we must put an end to the djaradin's advance once and for all.", objectives = "Defeat the djaradin forces and stop their advance in the Battlefield Ruins.", completion = "This must be the nesting area mentioned in the stolen report.\n\nBut why are the djaradin here dead?\n\nAre we too late?" }
WordHunterWoW_QuestEN[74557] = { title = "Investigating the Unknown", description = "We can only assume that something ambushed the marching djaradin. Who could have done this? \n\nWe should investigate it before we proceed.", objectives = "Investigate the origins and motivations of the creatures in the area.", completion = "So, the djaradin were stopped here by an unknown dragonkin force. Judging by how many lie dead, these dragonkin are as brutal as the djaradin. \n\nWhat worries me the most is that they still carry Neltharion's banner, which means they remain loyal to him and whatever task he once gave them. \n\nWe must be careful--this has just got more complicated." }
WordHunterWoW_QuestEN[74562] = { title = "Break Them Out", description = "Cages, chains and transportation carts... I think we all know where this leads.\n\nIf the drakonids plan on capturing and enslaving the slitherdrakes, then they are no better than the djaradin. \n\nSee what you can do to thwart their plans.", objectives = "Disrupt the poachers and stop them from capturing the slitherdrakes.", completion = "The slitherdrakes are free! Well done, <name>." }
WordHunterWoW_QuestEN[74563] = { title = "Worst of the Worst", description = "Everything here suggests this is a well-coordinated effort. These slitherdrakes are almost like wild beasts. They will not stand a chance without our aid.\n\nFind whoever is leading their operation and put an end to this.", objectives = "Find and eliminate drakonid leading the poachers.", completion = "So the slitherdrakes were not born here, but inside Aberrus?   Were they part of his experiments that ultimately led to the creation of the dracthyr? When I think about that, it horrifies me how easy it was for Neltharion to both create and destroy life.   Nevertheless, that was a decisive blow to their operation." }
WordHunterWoW_QuestEN[74568] = { title = "They Who Would Burn Us", description = "The djaradin and their Primalist allies are a stain upon the land, {name}.\n\nWipe them from it.", objectives = "Slay djaradin and Primalists assaulting the Ohn'ahran Plains.", progress = "How goes the battle?", completion = "Good. Nothing stops a ritual quite like killing the ritualist." }
WordHunterWoW_QuestEN[74569] = { title = "Deny Them Resources", description = "This entire invasion has been carried out with the sole objective of infusing raw materials with elemental power on an unprecedented scale.\n\nWhile we may not know Fyrakk's ultimate goal, frustrating his efforts seems straightforward enough.\n\nIf he wants these materials, we will deny them to him.", objectives = "Recover infusion supplies from Fyrakk's forces.", progress = "Leave him nothing.", completion = "Excellent. Anything we can take from him buys us time." }
WordHunterWoW_QuestEN[74570] = { title = "Aid Our Wounded", description = "{name}, our forces were not prepared for such an onslaught.\n\nThese djaradin fight with more furor than the forces we have faced in the past. We have wounded behind enemy lines.\n\nIf you possess knowledge of how to heal then I ask you employ it. If you do not, we have bandages to aid the wounded with. \n\nPlease help bring our people out of the fire.", objectives = "Heal 6 Wounded Guardians using the provided bandages or your own abilities.", progress = "Our healers cannot be everywhere at once. Nor will they last long behind enemy lines.", completion = "Many have fallen to these invaders who desecrate our sacred plains. Thank you for stemming the tide of death today." }
WordHunterWoW_QuestEN[74571] = { title = "Clear a Path", description = "The djaradin are fortifying their beachhead. We cannot allow them to dig in any deeper or we risk their advances becoming permanent.\n\nDestroy their barricades before that can happen.", objectives = "Destroy djaradin barricades.", progress = "Leave them nothing to cower behind.", completion = "With their defenses broken, it will be that much easier to repel their advances." }
WordHunterWoW_QuestEN[74572] = { title = "Make it Rain", description = "The djaradin are setting the Plains ablaze with the reckless use of fire magic. We must act before these small sparks grow into a raging wildfire.\n\nA deep pool of fresh water can be found not far from here. Skim the surface on your drake to collect as much as you can carry, then fly over the djaradin camp to douse any flames beneath you.\n\nThis won't be enough to put out the larger blazes, but it will buy us time.", objectives = "Extinguish fires across the djaradin camp.", progress = "Quickly, before the blaze spreads!", completion = "I could see the plumes of steam from here. Excellent work, <name>." }
WordHunterWoW_QuestEN[74573] = { title = "Aerial Support", description = "The Primalist portals must be destroyed if we are to prevent them from infusing these raw materials with elemental energy.\n\nUnfortunately, their structures are too heavily warded for any single attack, whether mortal or draconic, to do lasting harm.\n\nTogether, though, there is a way.\n\nTake this seed. Use it to weaken their defenses and we will be able to strike before they have a chance to react.", objectives = "Weaken the portals' defenses.", progress = "We are counting on you, <class>.", completion = "Well done. That should put them behind schedule." }
WordHunterWoW_QuestEN[74576] = { title = "Restored Hakkari Bijou", description = "<The bijou fragments fit together with ease; drawn toward each other with minimal intervention.\n\nIt thrums gently with remnants of an ancient power. Too much to be of no consequence, yet too little to be of much use.\n\nSomeone, somewhere, would surely be interested in seeing your discovery.>", objectives = "Find somebody interested in the Restored Hakkari Bijou.", completion = "An old Hakkari bijou, eh? I dare not ask HOW you came into possession of it, but there is no mystery to its origin.\n\nShould you find yourself within the walls of Zul'Gurub again, keep an eye out for other treasures... and bring them to me.\n\nI will be seeing you again soon." }
WordHunterWoW_QuestEN[74581] = { title = "The Long Knives", description = "Have you learned anything about Gor'krosh?", objectives = "Talk to Kaltunk in the Valley of Trials.", completion = "Is that you, <name>? Look at how much you've grown! But why are you here? \n\nThey've sent you to deal with Gor'krosh? Thank the ancestors!" }
WordHunterWoW_QuestEN[74636] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[74695] = { title = "Zulian, Razzashi, and Hakkari Coins", description = "", objectives = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", completion = "Excellent - this set of coins will make a fine addition to my growing collection.\n\nHere's your token, as promised." }
WordHunterWoW_QuestEN[74696] = { title = "Gurubashi, Vilebranch, and Witherbark Coins", description = "", objectives = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", completion = "Excellent - this set of coins will make a fine addition to my growing collection.\n\nHere's your token, as promised." }
WordHunterWoW_QuestEN[74697] = { title = "Sandfury, Skullsplitter, and Bloodscalp Coins", description = "", objectives = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", completion = "Excellent - this set of coins will make a fine addition to my growing collection.\n\nHere's your token, as promised." }
