WordHunterWoW_QuestEN[74769] = { title = "Stemming the Irontide", description = "Unfortunately, we are not the only ones who took notice of opportunities in the Reach. \n\nOur scouts have sent word of pirate vessels moored offshore. The first longboats have apparently come ashore on our northeastern beaches.\n\nOur history is not theirs to plunder. If you come across these pirates, send them swimming back to their little boats.", objectives = "Slay 10 Irontide Pirates on the Tempest Coast.", completion = "You have my thanks. With luck, these brigands will take heed.\n\nWe're willing to defend these lands and the secrets they contain." }
WordHunterWoW_QuestEN[74771] = { title = "Key Hunting", description = "My pockets are empty. I have no more vault keys!\n\nSee if you can find any Zskera Keys, and Jeb and I will see what we can find. If we pool our keys, we can open a lot of doors.", objectives = "Find 3 Zskera Vault Keys in the Forbidden Reach and deliver them to Pathfinder Tacha.", progress = "Did you find any keys?", completion = "We also found some keys! I can't wait to open more doors!" }
WordHunterWoW_QuestEN[74774] = { title = "More Keys", description = "I have more keys! You can use these to open more locked doors!\n\nPlease, take these and use them within the chamber.", objectives = "Take the keys.I have more keys! You can use these to open more locked doors!\n\nPlease, take these and use them within the chamber.You will be able to choose one of these rewards:" }
WordHunterWoW_QuestEN[74775] = { title = "Disciple of Fyrakk: Kretchenwrath", description = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", objectives = "Collect the Head of Kretchenwrath.", progress = "I heard you faced a disciple of Fyrakk.", completion = "So this is the beast who would swear their loyalty to such an Incarnate. Their zealotry has festered for ages upon ages of this world. \n\nI cannot even begin to fathom such a deep-seated hatred.\n\nThank you for ending this flame of wrath upon our plains." }
WordHunterWoW_QuestEN[74783] = { title = "The Sound of Silence", description = "It has been so many years since Shandaral has known true silence. With luck, our actions today will allow the echoes of this cursed place to fade.\n\nYou are due back in the Isles, no doubt--and I think it is high time I fly there as well.", objectives = "Return to Kalecgos in the Azure Span.", completion = "The aftermath of the conflict in Shandaral has hung over our flight like a pall for so many years. To think that Lanigosa has been toiling all this time to lay those spirits to rest...\n\nThank you for lending her your aid, <name>. You have once again shown yourself a true ally to my people." }
WordHunterWoW_QuestEN[74784] = { title = "Forbidden Reach 1/3 (FR)", description = "", objectives = "" }
WordHunterWoW_QuestEN[74786] = { title = "Snailspiration: Shimmershell Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Shimmershell Snail battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Well, that shimmershell certainly lives up to its name! Practically glowing brighter than this cavern's crystals. \n\nAbsolutely stunning snailwork, <name>." }
WordHunterWoW_QuestEN[74787] = { title = "Come Snail Away", description = "Hmm. You ever mount a snail before?\n\nI've trained generations of racing snail champions, but now I've come across my toughest case yet. Problem is he's too crokin' big. Straight up barred from competition.\n\nIt's a shame to keep such a prize specimen stuck in a bucket though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", objectives = "Introduce yourself to Slick.", progress = "The big guy's racing name is Big Slick in the City, but we just call him Slick.", completion = "He likes you! Well, he doesn't dislike you. Hard to tell with snails.\n\nNow you just need to come back here every day for Slick's training regimen. He may be slow now, but we'll get him up to speed." }
WordHunterWoW_QuestEN[74792] = { title = "They're Full of Stars!", description = "", objectives = "Defeat Stargazer Zenoth in a Pet Battle" }
WordHunterWoW_QuestEN[74794] = { title = "Right Twice a Day", description = "", objectives = "Defeat the Malfunctioning Matrix in a Pet Battle." }
WordHunterWoW_QuestEN[74795] = { title = "An Odd Round Object", description = "<This object looked out of place in the Zskera Vaults. It is round, with three claw-like divots in it. Perhaps it is of interest to Voraxian.>", objectives = "Bring the Odd Round Object to Voraxian in Rusza'thar Reach.\n\nProvided item:", completion = "Hmm, round... clearly claw holes... squishes a bit... I have no idea what this is. Perhaps some form of thrown weapon?\n\nHow exciting!" }
WordHunterWoW_QuestEN[74796] = { title = "A Dusty Vase", description = "<You have found a vase. It appears to represent a black dragon fighting what could be a djaradin. It could be something Voraxian is interested in.>", objectives = "Bring the Dusty Vase to Voraxian in Rusza'thar Reach.\n\nProvided item:", completion = "<Voraxian holds the vase up to eye level and squints at the carvings.>\n\nHmm, yes, I think you are right <name>. It does look like a djaradin. \n\nIt is a vase though. Unlikely to be too exciting. Do not get your hopes up." }
WordHunterWoW_QuestEN[74835] = { title = "Enok the Stinky", description = "", objectives = "Defeat Enok the Stinky in a Pet Battle." }
WordHunterWoW_QuestEN[74836] = { title = "A New Vocation", description = "", objectives = "Defeat Izal Whitemoon in a Pet Battle" }
WordHunterWoW_QuestEN[74837] = { title = "Paws of Thunder", description = "", objectives = "Defeat Vikshi Thunderpaw in a Pet Battle" }
WordHunterWoW_QuestEN[74838] = { title = "Lyver", description = "", objectives = "Defeat Lyver in a Pet Battle." }
WordHunterWoW_QuestEN[74839] = { title = "Crystal Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74840] = { title = "Sharp as Flint", description = "", objectives = "Defeat Morgrum Emberflint in a Pet Battle" }
WordHunterWoW_QuestEN[74841] = { title = "Adinakon", description = "", objectives = "Defeat Adinakon in a Pet Battle." }
WordHunterWoW_QuestEN[74842] = { title = "Crystal Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74847] = { title = "Emberthal Awaits", description = "We are by no means ready to relax, but at least our encampment here is stable... for the time being. I should be able to handle the rest of our operation from here.\n\nEmberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. It would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.", objectives = "Meet with Emberthal above the cliffs of Morqut Village.", completion = "This was our training ground... and for many, it became our resting place.\n\nSo many secrets remain here. So many questions. With luck, we will find answers." }
WordHunterWoW_QuestEN[74857] = { title = "Mouse Detective", description = "Normally I'd chase strangers off my property, but today's an exception.\n\nMy sniffin' mouse has gone missing. It's not like Persii to ignore me when I call for her...\n\nI can't smell as good as other niffen, so I can't tend to the harvest without her help.\n\nPoor thing must be so scared, out there all on her own. Please, you gotta find Persii!", objectives = "Search for the missing mouse.", completion = "That niffen needs his mouse, huh? Hmm..." }
WordHunterWoW_QuestEN[74858] = { title = "Agrulculture", description = "The niffen say that sniffin' mice have great noses. They can make their way through the caverns and track down the fastest racing snails. Even sniff out glow spores ready for harvest.\n\nBut I have a good nose, too. Maybe I could even sniff out those glow spores!\n\nLet's collect the harvest for the hermit. That will show him it's okay that his mouse friend isn't here--because I can fill in!", objectives = "Collect 6 Glow Spores.", progress = "Sniffin' mice must make this a lot easier. But I don't mind hard work!", completion = "See? Just as good as a sniffin' mouse!\n\nI hope the hermit agrees..." }
WordHunterWoW_QuestEN[74859] = { title = "Sporemoth Exterminator", description = "Looks like sporemoths are wrecking these crops.\n\nIf they keep eating all the spores, the hermit won't have anything to harvest.\n\nWe need to cull the sporemoths. That should help keep the harvest thriving--and show that I know how to take care of a farm.", objectives = "Kill 10 Sporemoths.", progress = "If we don't keep the pests under control, the spores won't grow.", completion = "That should help keep the spores healthy for now." }
WordHunterWoW_QuestEN[74860] = { title = "A Friendly Introduction", description = "It's time to deliver the harvest to the hermit. When he sees what good work we did, maybe he'll hire me as a farmhand!\n\nI, uh... tried talking to him once before. Wanted to ask if he needed a helper.\n\nDoesn't seem to like guests, though. Especially drogbar. So I got nervous and ran off.\n\nYou were looking for his mouse. Could you introduce us?", objectives = "Deliver the harvest and introduce Agrul to Yarren.", progress = "You have to find Persii before it's too late!", completion = "That drogbar ran off because he's guilty. I'm sure of it!" }
WordHunterWoW_QuestEN[74861] = { title = "An Unfriendly Confrontation", description = "I knew I recognized that drogbar's voice.\n\nHe probably took Persii. I bet he knows where she is!\n\nPlease, {name}, you gotta track down that big bully. Do whatever it takes to get Persii back!", objectives = "Find Agrul.", completion = "I never should have worked for Malrogg..." }
WordHunterWoW_QuestEN[74862] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[74864] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[74866] = { title = "Journal Entry: Experiments", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Collect a Journal Entry.", progress = "<name>, find any information of interest?", completion = "Good. More of our history in the voice of someone who lived it.\n\n<Azurathel reads over the journal entry growing more and more stoic.>\n\nThis is... disturbing. As soldiers we knew there was a degree at which we were expendable. But to read this...\n\nThank you for bringing this to me. We need to get this translated so others can read it." }
WordHunterWoW_QuestEN[74867] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[74869] = { title = "Primordial Answers", description = "Revelations await us within this vault. Perhaps we'll find a way to protect ourselves against Primalist magic. The elementals hiding in these vaults are wild, ancient, and free of Primalist control. Perhaps they hold the secret to helping the elementals on the surface.\n\nI have an idea. We'll need four primordial cores. Then we can construct a talisman that can purify and remove the influence of Primalist control from the elementals outside.\n\nIf you help us, I will share what we have found here.", objectives = "Obtain a Primordial Earth, Fire, Water and Storm Core from the elementals within the Zskera Vaults.", progress = "Have you found the cores?", completion = "These primordial cores are all I need here. \n\nPlease let me share with you the things I have found. May they help you in your efforts." }
WordHunterWoW_QuestEN[74871] = { title = "Sparks of Life: The Forbidden Reach", description = "The Forbidden Reach is enveloped with the vibrancy of the Dragon Isles.\n\nGo explore and capture sparks, but stay wary for any combatants you may encounter.", objectives = "Collect 50 Sparks of Life in The Forbidden Reach, while in War Mode.", progress = "Right out that door. Can't miss it.", completion = "The Accord thanks you, no doubt." }
WordHunterWoW_QuestEN[74874] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[74875] = { title = "A Spring Awakening", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities - Razor Hill, Brill, Bloodhoof Village, and Falconwing Square - who have been recruiting egg hunters for help with some research they're doing. I'm not sure of the particulars, but I'm sure they'd tell you.", objectives = "Talk to a Spring Gatherer in Razor Hill, Brill, Bloodhoof Village, or Falconwing Square.", completion = "Yes! Yes, I think I have just the task for you..." }
WordHunterWoW_QuestEN[74876] = { title = "The Buddy System", description = "Oh, hello there. Was I speaking my thoughts out loud again?\n\nI don't mean to trouble others with my problems, but...\n\nI'm a sniffenseeker, you see. We find unique and amazing places all over the cavern! But we have an important rule here in Loamm--we always follow the buddy system. Nobody digs alone!\n\nI've had the same buddy since we were pups, but she's too busy to dig anymore. I found this interesting new smell. Before, I had a buddy...\n\nSay, how do you feel about being a stand-in dig partner?", objectives = "Go on a dig adventure with Myrrit.", progress = "Just let me know if you decide you'd like to go with me!", completion = "You're a good partner. We should do more digs together. We could even have a dig team name! Like... the diggies? Duggies? I'll think about it.\n\nI'm not sure when my main dig buddy will have time to go again, so I'm glad to have met you, friend!" }
WordHunterWoW_QuestEN[74877] = { title = "Best Friends", description = "Really, I have fun digging with you. I do! Please, don't take this badly, but... I miss my best friend.\n\nI don't blame her for being busy. She was kidnapped, and she is the princess! I know she doesn't have lots of time. I just wish... \n\n...I don't know.\n\nMaybe I wish things were the way they used to be, when she wanted to dig with me.", objectives = "Set up a dig for Myrrit and Effervesta.", progress = "It's Effervesta's favorite snack...", completion = "Maybe she forgot, or she's still busy." }
WordHunterWoW_QuestEN[74878] = { title = "Old Friends, Dear Friends", description = "I don't want to give up on my best friend, but what if she doesn't want to be friends anymore?\n\nWe've been dig buddies since we were tiny pups. Maybe it matters to me more than it does to her.\n\nWhat do I even say?", objectives = "Help Myrrit talk to Effervesta.", progress = "Why is this conversation so difficult?", completion = "I think I'm okay now, <name>.\n\nWe can still be best friends even if we don't do digs anymore. And I have new friends like you to dig with.\n\nI'm glad I got this off my chest." }
WordHunterWoW_QuestEN[74879] = { title = "Corrosive Counterbalance", description = "", objectives = "" }
WordHunterWoW_QuestEN[74880] = { title = "Journal Entry: Relics", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Collect a Journal Entry.", progress = "<name>, find any information of interest?", completion = "I think I remember Ebyssian talking about the Hammer of Khaz'goroth and how it was used to expunge him of corruption.\n\nGiven it did not work on us I can only assume I was never corrupted. I am taking this as a win!\n\nThank you for this information, <name>. I will add this to our collection." }
WordHunterWoW_QuestEN[74882] = { title = "Crystal Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74883] = { title = "Journal Entry: The Creches", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Journal Entry.", progress = "Have you found any more journal entries of Adamanthia?", completion = "This is just creepy. I know what happened and yet this is crawling up my scales like one of those annoying beetles. \n\nI will get a translated copy added to the collection so others can read it. \n\nI am very much wondering whose side this Adamanthia was actually on." }
WordHunterWoW_QuestEN[74889] = { title = "Caldera Cruise", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74892] = { title = "Zaqali Elders", description = "", objectives = "" }
WordHunterWoW_QuestEN[74896] = { title = "Journal Entry: Silence", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Journal Entry.", progress = "This may prove quite insightful.", completion = "So they kept us secret even from the other aspects. Malygos knew, but from what I have heard, he could be just as disconnected as Neltharion.\n\nI will add this journal entry to our translated collection. Thank you, <name>." }
WordHunterWoW_QuestEN[74899] = { title = "Caldera Cruise - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74900] = { title = "Receiving Stone: Final Warning", description = "<This receiving stone still holds ancient words from Neltharion in an old draconic dialect.>\n\n<The dracthyr scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Receiving Stone.", progress = "What have you found?", completion = "Oh... I remember that tone of voice. \n\nI am starting to think Adamanthia may have crossed a line, and she could not walk back.\n\nI will get the translation of this stone added to our transcripts." }
WordHunterWoW_QuestEN[74901] = { title = "Sending Stone: Protest", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Sending Stone.", progress = "What have you found?", completion = "Well, good to see a black dragon standing up for us, even if it was too little too late.\n\nI wonder what this \"Aberrus\" is. If it is another place where dracthyr were held then we may need to find it.\n\nI will add this to the translated logs. I recommend taking a look as you find more of these." }
WordHunterWoW_QuestEN[74902] = { title = "Sending Stone: Initial Report", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Sending Stone.", progress = "What have you found?", completion = "They knew we were not broken.\n\nTHEY KNEW.\n\nI think we knew that, but to read this... it just feels like more oil on the pyre. \n\nStill, I thank you for bringing this to us. I will get this translated for everyone to read and added to the logs." }
WordHunterWoW_QuestEN[74903] = { title = "Sending Stone: The Prisoner", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", objectives = "Find a Sending Stone.", progress = "What have you found?", completion = "Huh. If this is right, then Raszageth was awake the entire time we were in stasis.\n\nI can see why she was so mad. I still do not agree with her or her methods, but anyone trapped for more than ten or twenty thousand years in a hole with little light is going to go mad. \n\nI will get the translated version added to the transcripts we have been handing around. Thank you for this, <name>." }
WordHunterWoW_QuestEN[74905] = { title = "Researchers Under Fire", description = "", objectives = "" }
WordHunterWoW_QuestEN[74906] = { title = "Researchers Under Fire", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[74908] = { title = "New Adventures", description = "Cataloger Daela is here to investigate places of wonder and mystery. Skyfox Den and Caldera of the Menders look especially promising.\n\nCompleting her quests will unlock her Envoy Tasks today. You will be able to unlock other factions' Envoy Tasks tomorrow.", objectives = "Speak with Cataloger Daela.", completion = "Fascinating! We must plan our next steps wisely. I'll give you detailed instructions." }
WordHunterWoW_QuestEN[74909] = { title = "New Catches", description = "Turik is here to investigate the riches of the sea across the Forbidden Reach on behalf of the Iskaara Tuskarr.\n\nCompleting this quest will unlock his Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", objectives = "Speak with Turik.", completion = "The fish are really biting today!" }
WordHunterWoW_QuestEN[74910] = { title = "New Foes", description = "Storykeeper Ashekh is here to scout for enemies of the Maruuk.\n\nCompleting this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", objectives = "Speak with Storykeeper Ashekh.", completion = "Let me consider our enemies' strength. There is much to be done." }
WordHunterWoW_QuestEN[74911] = { title = "New Horizons", description = "Kraxxus represents the strength of Valdrakken Accord here on Forbidden Reach.\n\nCompleting this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", objectives = "Speak with Kraxxus.", completion = "Welcome to the Forbidden Reach, friend!" }
WordHunterWoW_QuestEN[74912] = { title = "Neltharion's Legacy", description = "<As you stare into the cracked titan gem, a voice echoes through your mind.>\n\n{name}! This is Nozdormu. \n\nThe time to redeem the legacy of your creator, Neltharion, is at hand. \n\nYou hold a vital piece to the artifact Neltharion once used to control you and all of the dracthyr.\n\nMeet me in Valdrakken. There is much to discuss.", objectives = "Meet Nozdormu in Valdrakken.", completion = "Thank you for coming. I have been preparing for this moment for quite some time." }
WordHunterWoW_QuestEN[74913] = { title = "Memories of an Artifact", description = "Emberthal aided me in discovering the Oathbinder. This was the artifact Neltharion used to control you all.\n\nI have been scouring the timeline to discover how it was made to forge a counterpart to it to protect your kind.\n\nThis gem you've recovered is just the key I need to move my studies forward.\n\nYou and I shall next meet within Zaralek Cavern, where you once fought over the broken Oathbinder.\n\nIt is there we will find the secrets to forge your own weapon to fight against tyranny.", objectives = "Meet Nozdormu within Zaralek Cavern.", progress = "Let us see what we find within the caverns.", completion = "You hold the memories of how to forge the counter to the Oathbinder. \n\nIt is time for you to embark on this path." }
WordHunterWoW_QuestEN[74923] = { title = "It Takes a Village to Make an Artifact", description = "You must go now and seek aid to create the key components to forge a new glove.\n\nEssence of Order is normally difficult to find, but the memories you have acquired will allow you to recover them at many locations.\n\nThis new glove will be one to empower your allies and your community... which means you will have to rely on others to aid you in this.\n\nTake the memories you've recovered and use them to teach others how to craft these parts.", objectives = "Use the Ancient Memories to teach others or yourself how to forge the parts needed for your new artifact.\n\nYou must use Work Orders to get the components from your allies.", progress = "Have you recovered all the items? You will have to request the aid of your fellow adventurers to create all the pieces.", completion = "Fine work! You've gone through great lengths to craft these individual parts. \n\nNow we must uncover the last part to bring it all together.\n\nThe essence of the first black dragon aspect." }
WordHunterWoW_QuestEN[74924] = { title = "Nasz'uro, the Unbound Legacy", description = "Through my research, I've uncovered the last piece to make this artifact truly a counter to the Oathbinder.\n\nThe essence of Neltharion.\n\nIt is here that I can finally aid the dracthyr. We shall travel to the Maelstrom to see his final moments.\n\nWith his essence, we shall finish crafting your artifact, Nasz'uro, the Unbound Legacy.\n\nSpeak to me when you are ready.", objectives = "Speak with Nozdormu to travel to the Maelstrom to view Neltharion's defeat.", completion = "Your artifact is now complete. Wield it knowing no one may ever control the <race> ever again. Your destiny is your own." }
WordHunterWoW_QuestEN[74925] = { title = "Caldera Cruise - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74939] = { title = "Brimstone Scramble", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74942] = { title = "Grime Lies Where You're Killing Slimes", description = "Did you see that? Some of the slimes are leaving little piles of grime behind. Hmm...\n\nMelly makes stuff out of all kinds of things. You think she could use the grime to help out Tempo? I bet she could.", objectives = "Collect Time Grime.", progress = "Time grime! I'm on a roll here.", completion = "Nice! I'll hand these off to Melly. Along with my list of excellent slime rhymes." }
WordHunterWoW_QuestEN[74943] = { title = "Brimstone Scramble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74944] = { title = "Brimstone Scramble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74945] = { title = "Guanite Gambit", description = "", objectives = "" }
WordHunterWoW_QuestEN[74946] = { title = "A Place of Refuge", description = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n{name}, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.", objectives = "Meet Baine and Tomul at Toghusuq Village.", completion = "The good news is that we have found the other tauren.\n\nThe bad news is that this Bovan he seeks isn't here.\n\nThe irritating news is that everyone wants me dead." }
WordHunterWoW_QuestEN[74948] = { title = "Snailspiration: Amethyst Softshell", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Amethyst Softshell battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Crok, what a beaut. And they come from the ocean? Can't imagine one of my snails handling all that salt. \n\nI'm sure Slick is impressed." }
WordHunterWoW_QuestEN[74949] = { title = "Snailspiration: Archetype of Vigilance", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Archetype of Vigilance battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "That... is the weirdest, fanciest snail I have ever seen.\n\n If Slick isn't impressed by this fellow, I don't know what's going to impress him." }
WordHunterWoW_QuestEN[74950] = { title = "Snailspiration: Blackchasm Crawler", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Blackchasm Crawler battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Now THIS is a snail who enjoys a good cavern! I'm sure Slick can relate. \n\nI certainly do." }
WordHunterWoW_QuestEN[74951] = { title = "Shimmering Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74952] = { title = "Snailspiration: Microlicid", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Microlicid battle pet and show it to Briggul.", completion = "Not sure what's so micro about that critter, but they sure got a shell on them. Though I guess most snails are micro next to Slick!" }
WordHunterWoW_QuestEN[74953] = { title = "The Heavy Crown", description = "I was really down when Effervesta didn't come like she said she would.\n\nBut I understand that she's so busy, what with being kidnapped and all of her duties. I don't blame her.\n\nI want to tell her how much that time meant to me when we were pups, though. That I'll be here for her if she ever needs me. Then at least she knows I'm still here.\n\nCan you help me get her attention long enough to say what I need to?", objectives = "Help create a time for Myrrit to talk to Effervesta.", progress = "I don't want to bother her...", completion = "Now that I have her here, I don't know what to say!" }
WordHunterWoW_QuestEN[74954] = { title = "Shimmering Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74955] = { title = "An Egg-centric Discovery", description = "Have you seen the new eggs this year? Well, you could say they are quite egg-citing!\n\n... Well, I'll get to the point. These new eggs that we've discovered will appear and vanish within minutes! That sounds quite egg-straordinary, right?\n\nLet me know when you're ready and we'll see to it that those eggs appear, but be quick! They'll be gone before you know it.\n\nI'll trade you a more permanent egg when you return with vanishing eggs.You will receive:", objectives = "Talk to a Spring Gatherer in Razor Hill, Brill, Bloodhoof Village, or Falconwing Square." }
WordHunterWoW_QuestEN[74956] = { title = "Shimmering Slalom - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[74959] = { title = "Snailspiration: Mudshell Conch", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Mudshell Conch battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Some people see a mudshell conch and think, what's so special? But me, I appreciate the simple things. There's beauty in that. \n\nI'm sure Slick agrees!" }
WordHunterWoW_QuestEN[74960] = { title = "Snailspiration: Predatory Helicid", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Predatory Helicid battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Predatory, huh? Just keep that critter away from my buckets. I don't need any accidents. Not again.\n\n<Briggul stares off at the distance, her eyes haunted.>\n\nBut yeah, I'm sure Slick is feeling that fighting spirit." }
WordHunterWoW_QuestEN[74961] = { title = "Snailspiration: Prismatic Softshell", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Prismatic Softshell battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Prismatic, huh? That's a fancy term for pretty colors? Well this snail fits the bill. I hope Slick doesn't get too self-CONCH-scious about it. Ha! \n\nHe's plenty pretty himself." }
WordHunterWoW_QuestEN[74962] = { title = "Snailspiration: Rapana Whelk", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Rapana Whelk battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Don't let that one fool you, <name>. I can sense the shell of a killer. Hope Slick is more inspired than spooked!" }
WordHunterWoW_QuestEN[74963] = { title = "Snailspiration: Rusty Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Rusty Snail battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Oh! Rusty like the COLOR. I was worried how you were caring for this little one. Made me scared for Slick here!\n\nWhew, that's a relief." }
WordHunterWoW_QuestEN[74964] = { title = "Snailspiration: Scooter the Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Scooter the Snail battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Look at the shell on that one! And you said a child gave them to you?\n\nGlad they ended up in your hands! Runts tend to behave... questionably toward snails." }
WordHunterWoW_QuestEN[74965] = { title = "Snailspiration: Shelly", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Shelly battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Now \"Shelly\" is a name I can get behind. Maybe this critter is Slick's long-lost cousin!\n\n<Briggul looks over the progenitor snail again.>\n\nHuh. Maybe... very long-lost." }
WordHunterWoW_QuestEN[74966] = { title = "Snailspiration: Silkbead Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Silkbead Snail battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Just look at that critter move! The silkbead snail has a particularly silky consistency to its mucus. \n\nNot sure Slick can really learn from that, but hey. You can." }
WordHunterWoW_QuestEN[74967] = { title = "Snailspiration: Spireshell Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Spireshell Snail battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "I'm sure Slick a-SPIRES to be as strong as your snail there! Ha!\n\n<Briggul wipes a joyful tear from her eye.>\n\nI should bring that one to the next race. The other trainers are going to eat it up." }
WordHunterWoW_QuestEN[74968] = { title = "Snailspiration: Zoom", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", objectives = "Summon a max-level Zoom battle pet and show it to Briggul.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "That... that's ZOOM! The legendary racing snail of Highmountain!\n\nCrok me, I have to tell cousin Boomboom about this. What an absolute honor. For Slick as well, I'm sure." }
