WordHunterWoW_QuestEN[74994] = { title = "Hraxian's Unbreakable Will", description = "", objectives = "I have forgotten much in the course of my life. \n\nTwice now you have helped me recover a valuable memory.\n\n<Veritistrasz smiles faintly.>\n\nPerhaps I should take Tellywin up on his offer to write memoirs, if just for my own sake. \n\nYou have done so much for myself and these folks. I hope one day to repay the favor." }
WordHunterWoW_QuestEN[74996] = { title = "A Difficult Legacy", description = "Let us talk to Veritistrasz about this vase, {name}. \n\nI want to temper your expectations though. It is just a vase, but you never know. It could be exciting.\n\nMaybe it could point us to a cache of weapons?", objectives = "Talk to Voraxian and Veritistrasz at Rusza'thar Reach.", progress = "It is always a pleasure, <name>.", completion = "Thank you for being here, <name>. You have both given me a lot to think about.\n\nI will stay with Veritistrasz for now, but I look forward to when we next meet." }
