WordHunterWoW_QuestEN[75050] = { title = "An Eclectic Accord", description = "While the storm over the Reach was raging, I gathered allies for our eventual return. I want to ensure they have everything they need, but I can't welcome all of them personally.\n\nWould you be my envoy, {name}? Can you make sure they have what they need? We have few supplies to offer and a shortage of assistance. \n\nThe least I can do is offer my gratitude. Please thank them personally on my behalf.", objectives = "Speak with the newly-arrived denizens of Morqut Village.", progress = "I appreciate your aid. I would attend to our allies' concerns myself, but there are still many missing dracthyr.", completion = "I must thank you as well, <class>. Our allies have come to the Reach for many reasons. Their kindness humbles me.\n\nNow we need to follow through and do everything we can to make this place safe and prosperous." }
