WordHunterWoW_QuestEN[75145] = { title = "In the Wake of the Ashes", description = "We did all we could. We will return to help them rebuild, but for now... the people of Loamm need time to mourn.\n\nAlexstrasza must be informed of what happened here today. She must be warned what has been unleashed upon the Dragon Isles.\n\nWe will meet you at the Seat of the Aspects.", objectives = "Meet Ebyssian at the Seat of the Aspects in Valdrakken.", progress = "Everyone must know what happened.\n\nIt is the only way we can hope to prepare for the damage to come.", completion = "That is all we can do for now.\n\nSabellian, Wrathion, and I must plan our next steps as we prepare to return to Zaralek." }
WordHunterWoW_QuestEN[75146] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[75148] = { title = "Ancient Techniques", description = "I've heard tales that the djaradin forge their blades with magic so hot that they can actually quench the metal with lava. Lava! It's like ice water compared to the heat their magic creates! \n\nBut I've never been able to verify it for myself. They aren't exactly peddling their wares at the market.\n\nYou smell like battle, though. Go and fetch some of their weapons for the blacksmiths back in Loamm and we'll see if the legends are true, eh?", objectives = "Collect 8 Lava-Quenched Blades.", progress = "I find the tales hard to believe, but then again... they do live in magma pits!", completion = "<Crubus tries to accept the blades from you, but quickly yanks his hands back and shakes them out.>\n\nYEOW! How are you holding those so easily?!\n\nJust--just set them down. I'll get some gloves." }
WordHunterWoW_QuestEN[75149] = { title = "Obsidian Essays", description = "It's not common these days, but we do have a few of our histories in writing--well, carvings really. We can trace the etchings with our fingers! \n\nWe used to use clay tablets for this, but they were brittle, and prone to breaking. Not good if you want to preserve history!\n\nI hear the djaradin carve their important texts into volcanic glass. If they can manage that without shattering the tablets, we could probably learn a thing or two from their techniques!\n\nTake some samples back to Loamm for study.", objectives = "Collect 10 Obsidian Tablets.", progress = "New knowledge can come from the strangest sources!", completion = "Very interesting... they might look like brutes, but this carving requires a light and careful hand. Not to mention enormous amounts of patience.\n\nWith any luck, we'll both make something as fine as these one day, eh?" }
WordHunterWoW_QuestEN[75150] = { title = "Incandescence", description = "Some of our incense needs to be burned very slowly to release the right aromas. You can check the heat yourself, of course--but it gets to be a bother.\n\nFortunately, I've found a solution! If you grind up shards of fire elementals and sprinkle the dust over the incense, you can keep the heat consistent using enchantments. Completely hands-free!\n\nThose shards are a bit hard to come by, though. Could you find some and bring them to my friends back in Loamm?", objectives = "Collect 8 Everburning Fireshards.", progress = "Elder Honeypelt usually brings us back a stock of shards when she returns from a hunt, but I'd hate to bother her again so soon.", completion = "Wonderful! With this haul, I'll be able to keep our incense burning for weeks and still have some to spare." }
WordHunterWoW_QuestEN[75151] = { title = "Redistributing the Remnants", description = "", objectives = "" }
WordHunterWoW_QuestEN[75153] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[75154] = { title = "Waygate: Morqut Islet", description = "We have access tae The Forbidden Reach now, and Cataloger Daela is already waitin' fer ya there. \n\nShe's sent me a word of a very promising spire not far from the village where she's stayin'. \n\nThink there might be another dormant Waygate around? Go on an' find out!", objectives = "Locate the Dormant Waygate on the Morqut Islet in The Forbidden Reach.", progress = "Found anythin'?", completion = "I knew it!" }
