WordHunterWoW_QuestEN[75164] = { title = "In Need of Primal Foci", description = "", objectives = "The major factions of the Dragon Isles are looking to upgrade the gear of their warriors. \n\nDo you happen to have any Primal Foci you would be willing to donate to this effort? The faction you donate to is sure to take note.", progress = "The major factions of the Dragon Isles are looking to upgrade the gear of their warriors. \n\nDo you happen to have any Primal Foci you would be willing to donate to this effort? The faction you donate to is sure to take note.", completion = "Thank you!\n\nTell me which major faction you would like to donate these to, and I will make sure they hear about your generosity." }
