WordHunterWoW_QuestEN[75168] = { title = "Air Control", description = "We will never make progress while those shadowflame drakes have us pinned down from the air.\n\nGet up there and knock them from the skies.", objectives = "Slay or knock Primal Nightflames from the air with Whirling Surge.", progress = "They are not the only ones who can fly.", completion = "The skies are clearer already." }
