WordHunterWoW_QuestEN[75221] = { title = "Find a Rumble Coin", description = "To use this game machine, you need a Rumble Coin.\n\nThere are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later.\n\nI stashed one coin here in the Roasted Ram. If you find it, it's all yours, pal.\n\nInsert that Rumble Coin into the Rumble machine and watch the fun begin!", objectives = "Find a Rumble Coin in the Roasted Ram and insert it into the Warcraft Rumble machine.", progress = "<The Warcraft Rumble machine stands before you. A small sign reads:>\n\nInsert Rumble Coin to play.", completion = "<As you insert your coin, the fun little machine rumbles and jingles.\n\nYou got a prize!>" }
WordHunterWoW_QuestEN[75222] = { title = "Shellfire", description = "", objectives = "" }
WordHunterWoW_QuestEN[75223] = { title = "Warcraft Rumble Minis: New Look!", description = "<You find a message etched into the foil.>\n\nThis Rumble Foil can be used at a Warcraft Rumble machine. Go and get a new look for one of your minis!", objectives = "Go to the Warcraft Rumble machine in Valdrakken.", completion = "<The Warcraft Rumble machine has a hatch. It's the perfect size to insert a miniature toy and a Rumble Foil.>" }
WordHunterWoW_QuestEN[75230] = { title = "Reconcilable Dissidents", description = "My hope, {name}, is that our work to understand the rebels will allow us to find a path to peace.\n\nMy concern is if we are not able to come to an understanding with Belaphon, other rebels may see her as a martyr for the cause.\n\nWhatever happens, you have my gratitude for your assistance throughout this rebellion.", objectives = "Listen to Alexstrasza's conversation with Instigator Belaphon.", progress = "I hope Belaphon can see the way forward for Dragonkin.", completion = "This crisis has driven us to a better understanding of each other, and driven me to be a better leader.\n\nAnd we could not have found the way to peace without your help. <name>, thank you." }
WordHunterWoW_QuestEN[75232] = { title = "Fallen Effects", description = "<You wrap Sheridon's effects into a bundle, and place them in your pack to return to the camp members.>", objectives = "Return Sheridon Hastle's Effects to Earthmender Narvra in the Dragonscale Expedition camp in Zaralek Cavern.\n\nProvided item:", completion = "Oh... Sheridon... He bought our lives with his own. I... I will make sure his family gets these.\n\nI'll mark the location of his body, we'll have Rupert retrieve it so he can have a proper burial.\n\nThank you. Please, have this." }
WordHunterWoW_QuestEN[75233] = { title = "Flesh to Bone", description = "We found Skuttog near a cave to the north, by some nasty spiders. It seems like his skin is turning into bone.\n\nI can heal him, but I need venom from whatever bit him. Please help.", objectives = "Find the venom of the beast that bit Skuttog.", progress = "Please hurry. He's almost a statue already.", completion = "This should be enough. Let's see if it works." }
WordHunterWoW_QuestEN[75234] = { title = "Scratch and Sniff", description = "", objectives = "" }
WordHunterWoW_QuestEN[75237] = { title = "Reach West", description = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? \n\nI heard the windstreams in the western Forbidden Reach are especially good today. Why don't you try a few courses out there?", objectives = "Fly the race courses in the western Forbidden Reach.\n\nFinish any Advanced or Reverse course of the two to instantly complete the quest.", progress = "Having fun?", completion = "You both look you had quite a workout. Way to go!" }
WordHunterWoW_QuestEN[75239] = { title = "Disciple of Fyrakk: Shadeisethal", description = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", objectives = "Collect the Head of Shadeisethal.", progress = "That was a lot of fire. So many people burned.", completion = "This thing was so angry. Rage and fury festering for eons before my people first sailed the seas. I cannot even imagine that depth of hate.\n\nYou have put it to rest. I thank you, <name>, on behalf of all of those whose lives you have saved by slaying this beast." }
WordHunterWoW_QuestEN[75244] = { title = "Reunited Again", description = "Thanks to you, {name}, all of the blue dragons are accounted for. We can get back to caring for Azeroth's magic and making sure its power isn't abused.\n\nI believe a speech is in order. I would be honored if you would stay for it. \n\nWe can head to the Nexus afterwards to see what Azuregos has discovered about Sindragosa and Malygos's arcane memories.", objectives = "Listen to Kalecgos's speech.", progress = "It is good to see so many blue dragons returned.", completion = "It appears this was a short reunion." }
WordHunterWoW_QuestEN[75257] = { title = "The War Creche", description = "", objectives = "" }
WordHunterWoW_QuestEN[75258] = { title = "A Final Word", description = "I have sent a message to Mayla in Valdrakken, relaying what has happened here. I suspect she will be relieved to hear from me... and in knowing she was right to send you. \n\nBefore you leave, I would like to speak with you a moment.", objectives = "Speak with Baine.", completion = "<name>, there are few who would have gone to the lengths you have to aid me in this endeavor. You had no personal stake in this matter, yet you risked your life for my sake.\n\nFor this, you have my deepest gratitude. Should you one day require my assistance, you need only ask.\n\n\n\nAnd now there is one last person I must speak to." }
WordHunterWoW_QuestEN[75259] = { title = "Aiding the Accord: Zskera Vaults", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nPathfinders of the Dragonscale Expedition are delving deeper into the Zskera Vaults on the Forbidden Reach. They are asking for brave adventurers to help them explore these new mysteries.\n\nWe await your return, {name}.", objectives = "Travel to the Forbidden Reach to collect Zskera Vault Keys and use them to open doors in the Zskera Vaults. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", completion = "My, my. What wondrous news! The Accord will be most pleased by your efforts. \n\nPlease accept this as a token of our gratitude." }
WordHunterWoW_QuestEN[75261] = { title = "Reach Center", description = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? \n\nI heard the windstreams in the central Forbidden Reach are especially good today. Why don't you try a few courses out there?", objectives = "Fly the race courses in the central Forbidden Reach.\n\nFinish any Advanced or Reverse course of the two to instantly complete the quest.", progress = "Having fun?", completion = "You both look you had quite a workout. Way to go!" }
WordHunterWoW_QuestEN[75263] = { title = "Reach South", description = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? \n\nI heard the windstreams in the southern Forbidden Reach are especially good today. Why don't you try a few courses out there?", objectives = "Fly the race courses in the southern Forbidden Reach.\n\nFinish any Advanced or Reverse course of the two to instantly complete the quest.", progress = "Having fun?", completion = "You both look you had quite a workout. Way to go!" }
WordHunterWoW_QuestEN[75265] = { title = "An Urgent Matter", description = "<The agent fixes his eyes on you and nods.>\n\nI have an urgent letter for you, hero. Something has happened in the Keep. \n\nI recommend you see to its contents promptly. \n\nAnd keep this to yourself, hero.", objectives = "Meet Master Mathias Shaw on the outside ramparts behind Stormwind Keep.\n\nProvided item:", completion = "It's good you are here." }
