WordHunterWoW_QuestEN[75351] = { title = "Keep a Leather Eye Open", description = "The kith of Loamm request the skills of a leatherworker! We've heard of the wonders you uplanders make with hides and scales!\n\nWe have leatherworkers of our own down below! Miss Garram has heard there's a set of magical drums that make you faster! Is such a thing possible?\n\nMake a delivery to Loamm as soon as you can, won't you?", objectives = "Deliver Feral Hide Drums to Garamm in Loamm.", progress = "Did Kayann send you? Do you have what I asked for?", completion = "Aha! So these are the hastening drums? I'm hoping these will help me move faster and get more work done each day.\n\nWe niffen have drums of our own, but nothing like these! Let's try them out!" }
WordHunterWoW_QuestEN[75352] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[75353] = { title = "Dinn", description = "", objectives = "" }
WordHunterWoW_QuestEN[75354] = { title = "Mycelium Mastery", description = "Hey there, stranger! I had an idea to run by you.\n\nThe mushrooms that grow down in Zaralek Cavern have thick and powerful mycelium capable of gripping into even the hardest crystals.\n\nImagine the possibilities with such a material! I had a friend down in Loamm who was trying to work out how to make it into a leather!\n\nInterested? Bring my friend Garram some mushrooms!", objectives = "Collect 10 Nightlight Conkerbell Samples and deliver them to Garram in Loamm.", progress = "We call those crystal clinging mushrooms Nightlight Conkerbells. Not only do they give off light, they even have a strong enough scent to help guide our noses!", completion = "What? There's hardly any mycelium on these!\n\n<Garram thinks.>\n\nI wonder... do they leave it behind in the crystal? \n\nHmm... I'll try to grow more here and experiment. Thanks for the help!" }
