WordHunterWoW_QuestEN[75362] = { title = "Cephalo-crystalization", description = "Well, hello there!\n\nHave you seen those snails in Zaralek Cavern with the crystals growing from their shells? \n\nWhen crushed to powder and mixed with a proper solution of slime, those crystals make a paste that adds a considerable luster to our gems! Bring some to my good friend Fanilly, and I'm sure she'll be happy to chat your ear off about jewelcrafting!", objectives = "Collect 10 Whelkshell Crystals and deliver them to Fanilly in Loamm.", progress = "You know, a good shine on a gemstone is very important to us... we have such a hard time seeing it otherwise!", completion = "Oh yes, this will do! Now watch, just grind it together, then apply it to the gem and polish..." }
WordHunterWoW_QuestEN[75363] = { title = "Deepflayer Dust", description = "Why, I just got another letter from my good friend Mistie. She's been looking for interesting ingredient ideas for her smelly concoctions!\n\nA while ago, the kithguards took down a deepflayer near Loamm. I noticed a peculiar dust it shed when it perished. It had a unique aroma to it, and I'm sure Mistie would love to experiment with something like that!\n\nCould you gather some from the deepflayers near Loamm, then bring it to Miss Mistie? You'll be doing us a favor, too!", objectives = "Collect 10 Deepflayer Dust and deliver them to Mistie in Loamm.", progress = "Such a mysterious musty aroma... the grim note of death alongside the gentleness of soil.", completion = "Oh yes, this'll do nicely! Can you smell that with your nose? It's very fragrant!" }
WordHunterWoW_QuestEN[75364] = { title = "Emberdusk", description = "", objectives = "" }
WordHunterWoW_QuestEN[75365] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[75366] = { title = "Viridian King", description = "", objectives = "" }
WordHunterWoW_QuestEN[75367] = { title = "The Obsidian Rest", description = "It is a miracle this outpost survived so long after Neltharion's... disappearance. \n\nFor weeks now local scouts have reported increased djaradin activity in the area. They are amassing an army, and they are also becoming increasingly aggressive in their efforts to expand their territory.\n\nWe must take every possible precaution and try to understand our enemy's motivations.", objectives = "Gather information and resources at the Obsidian Rest.", progress = "These are trying times for all of us.", completion = "We must discuss what you have learned, <name>." }
WordHunterWoW_QuestEN[75368] = { title = "Stones and Scales", description = "I'm sure you've run into some of the mean beasties we have down in Zaralek while you were on your adventures! Have you seen any rock vipers yet? \n\nThey're covered in both scales and stones! And have massive fangs!\n\nMister Garram has offered a reward for anyone brave enough to bring him some of their hides! I'm sure he will make it worth your while!", objectives = "Collect 10 Scaly Stone Hides from rock vipers  in Zaralek Cavern.", progress = "Have you collected those hides yet? Those snakes are a little scary, but I think a <class> like you can handle them!", completion = "Wonderful! These'll do nicely. Look how hard and sharp the scales are!\n\nThanks for your help, friend! I'll let Kayann know if I need anything else." }
WordHunterWoW_QuestEN[75369] = { title = "Use Your Coin!", description = "Use that coin on the Warcraft  Rumble machine over there.", objectives = "Use that coin on the Warcraft  Rumble machine over there." }
WordHunterWoW_QuestEN[75370] = { title = "Smellincense", description = "", objectives = "" }
WordHunterWoW_QuestEN[75371] = { title = "Fascinating Fungi", description = "Ah, Uplander! Can I ask for your assistance?\n\nThe cavern below is full of mushrooms that are useful for all kinds of things! Miss Mistie has asked for help gathering them for her alchemical experiments.\n\nShe says the Gelcap mushrooms produce sticky spores that she can make into a balm, good for easing achy joints and bunions! I sure could use some after standing around on these hard stones all day!\n\nIf you can find her some, I'm sure she will make it worth your while!", objectives = "Collect 10 Gelcap Spores.", progress = "Have you collected the spores? I'm eager to get my hands on them!", completion = "These are incredibly sticky spores! Thank you, <name>! \n\nNext time you see Kayann, tell him I'll get him his balm soon--and some free sunscreen to boot! I don't know how he stands being up there all day!" }
WordHunterWoW_QuestEN[75372] = { title = "Drive Them Before Us", description = "Drive these whelks from our lands, {name}!\n\nFor Imbu! For the Azure Span!", objectives = "Slay djaradin and Primalists assaulting the Azure Span.", progress = "Glorious.", completion = "That'll leave a mark they won't soon forget!" }
WordHunterWoW_QuestEN[75373] = { title = "Charge of the Ottuk Brigade", description = "Bah! They hide behind their barricades, hoping that will protect them from our vengeance.\n\nClear the way and we will ride them down like the cowards they are!", objectives = "Destroy djaradin barricades.", progress = "Soon we shall ride again, <name>.", completion = "Prepare to taste our spears, Fyrakk!" }
WordHunterWoW_QuestEN[75374] = { title = "To Defend the Span", description = "The djaradin struck without warning, {name}. Our people are capable fighters, but no one escapes a battle like this unscathed.\n\nPlease, help with the wounded. Many are trapped behind the enemy lines and can't make their way back in their current state.", objectives = "Heal 6 Gruff Fishers using the provided bandages or your own abilities.", progress = "There are always more wounded that need healing.", completion = "Fewer deaths is always worth celebrating. We have lost enough as it is." }
WordHunterWoW_QuestEN[75375] = { title = "Burning Ice", description = "Whatever magic the djaradin are employing is lighting the ice on fire out there, {name}.\n\nWe can't let this spread to the wider Span. It has to be stopped before it consumes everything.\n\nGather as much water as you can while on that drake of yours and drown the fires. Hopefully that will be enough to extinguish them.", objectives = "Extinguish fires across the djaradin camp.", progress = "The sight of burning ice unnerves me.", completion = "Thank you, <name>. At least we can contain the damage." }
WordHunterWoW_QuestEN[75376] = { title = "Suffuse, Reuse, Recycle", description = "If Fyrakk is willing to openly attack the surface in pursuit of these materials, they must be vital to his plans.\n\nGrab whatever you can. There must be a way to turn these to our advantage.", objectives = "Recover infusion supplies from Fyrakk's forces.", progress = "We'll strengthen ourselves even as we deny our enemies.", completion = "Admirable work, <name>. They would not have let this go lightly." }
WordHunterWoW_QuestEN[75377] = { title = "Maintaining the Barricade", description = "It's all I can do to keep this shield up under the barrage these shadowflame drakes are putting out.\n\nThin their ranks before we're pinned down for good.", objectives = "Slay or knock Primal Nightflames from the air with Whirling Surge.", progress = "Incoming!", completion = "Excellent work. I might even be able to catch my breath before the next catastrophe." }
WordHunterWoW_QuestEN[75378] = { title = "Ashenvale Ambit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[75379] = { title = "Ashenvale Ambit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[75380] = { title = "Ashenvale Ambit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[75382] = { title = "Portal Combat", description = "The Primalists are channeling elemental forces through those portals, energizing their entire effort and speeding the production of these suffused ingots.\n\nSoon they will be stabilized enough to allow their elemental allies to pass through to reinforce their position.\n\nWe have to seal them before that happens or the battle may turn against us.\n\nTake this focus and disrupt the portals' protective runes, then we can strike from above. Only together do we stand a chance.", objectives = "Weaken the portals' defenses.", progress = "Together, <class>.", completion = "Excellent. That will at least stabilize the situation." }
WordHunterWoW_QuestEN[75383] = { title = "Hideaway No More", description = "This was supposed to be a peaceful retirement, not a warzone!\n\nGrab one of those totems the shamans left lying around and put out these fires before my dreams of a nice fishing retreat go up in smoke! Literally!", objectives = "Use a water totem to extinguish fires in Grimtusk's Hideaway.", progress = "Who burns down an ice fishing hut?", completion = "Good job, <race>. Maybe I'll get an afternoon to myself, yet." }
WordHunterWoW_QuestEN[75384] = { title = "Payback's a Mammoth", description = "Trying to kill me I can forgive, but attacking my Hideaway? Now it's personal.\n\nThe djaradin are loading their mammoths with all the ingots they can bear to get them back to their precious Fyrakk.\n\nHijack one and bring it back here, cargo and all.", objectives = "Mount an Overladen Mammoth and return it to your lines.", progress = "What are you waiting for? A thaw?", completion = "Now that's a statement!" }
WordHunterWoW_QuestEN[75385] = { title = "Durotar Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
