WordHunterWoW_QuestEN[75398] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in the Waking Shores.", completion = "Honor the Waking Shores flame." }
WordHunterWoW_QuestEN[75407] = { title = "Silk Scavenging", description = "Hello friend! You're a tailor, right? So you must know about silk!\n\nMister Rossmar down in Loamm knows how to make special silk from the cocoons of the Underlight Moths, but could use some help gathering them up! \n\nYou should be able to find them in the mushroomy area near Glimmerogg. I'll sure he will make it worth your while!", objectives = "Collect 10 Underlight Cocoons Fibers in Zaralek Cavern.", progress = "Hey, uplander! Do you have those cocoons yet?", completion = "These look great! Thanks, <name>!\n\nNow we just need to boil them and turn them into thread. Oh they make SUCH a smelly smell when you boil them.\n\nWhat's that? You have to go? Oh, ok!" }
WordHunterWoW_QuestEN[75408] = { title = "Calling All Dracthyr!", description = "<This flyer is illustrated with inviting sketches of dracthyr eating, sparring, and having fun.>\n\nCalling all dracthyr!\n\nDo you feel adrift after the events of the underground? Do you want to bond with your creche mates? Do you just need someone to talk to?\n\nCome join us at Weyrnrest for food, fun, and camaraderie! ALL dracthyr welcome!", objectives = "Go to the party at Weyrnrest in Valdrakken.", completion = "Everyone's tired, that much is clear. But this kind of togetherness is what will help us start healing.\n\nWhy don't you take a look around, talk to some <race>?" }
