WordHunterWoW_QuestEN[75440] = { title = "Satiating Sharpbeak", description = "Sheridon Hastle was our flight master and Sharpbeak's rider. After his death, she won't let anyone touch her.\n\n<Narvra clutches her side in pain.>\n\nOr feed her. Rupert tried but... she just won't.\n\nThe rest of us are too injured to move... I'm worried about her.\n\nCan you... ow... try? Someone new may get through to her. Her feed is in the bag by the tent.\n\nAnd... if you can get her to accept food, she might let you ride her.", objectives = "Feed Sharpbeak in the Dragonscale Camp in Zaralek Cavern.", progress = "<Sharpbeak looks at you mournfully.>", completion = "<Sharpbeak tentatively accepts the feed from you. \n\nAfter a few snapping bites, she looks you in the eye, spreads her wings and shakes them.\n\nYou feel as though she might let you ride her if needed.>" }
WordHunterWoW_QuestEN[75441] = { title = "Smelly Scramble", description = "", objectives = "" }
WordHunterWoW_QuestEN[75444] = { title = "Waygate Exploration: The Forbidden Reach", description = "<Another visit from Nanners, and another calling from the Dragonscale Expedition.\n\nIt seems Thaelin Darkanvil have something of an interest for you yet again.>", objectives = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.\n\nProvided item:", completion = "Good tae see ye again, <name>.\n\nThe Isles seem to be storin' endless opportunities fer adventure." }
