WordHunterWoW_QuestEN[75466] = { title = "Lost Time-Lost Vikings", description = "Some rowdy customers stumbled out of a temporal portal a bit ago. Before I could get a Timewalker to help get them home, they decided to visit Valdrakken.\n\nWould you find Olaf, Baelog, and Eric and get them to come back here before they cause too much of a ruckus?", objectives = "Convince the Lost Vikings to return to Eon's Fringe.", completion = "Those three had their fun, but it was high time they got back to their proper place." }
