WordHunterWoW_QuestEN[75493] = { title = "Surveying the Riverbed", description = "Hope you brought your boots, 'cause this is gonna be a wet one!\n\nThis river carries artifacts down from the mountains, and they wash up here in the silt. The centaur have found loads of stuff here over the years.\n\nWe're here to take a deeper look and see if there's anything interesting below the surface.", objectives = "Speak with Roska to start the dig, then excavate artifacts from the riverbed.", completion = "<Roska lets out a low whistle.>\n\nNow that's something you don't see every day. Let's get her out of there." }
WordHunterWoW_QuestEN[75494] = { title = "Strike the Colors", description = "", objectives = "" }
WordHunterWoW_QuestEN[75497] = { title = "The Catalyst's Boon", description = "I have an urgent message for you, adventurer.\n\nThe Revival Catalyst seems to be responding to the land's rumblings--perhaps even your feats!\n\nMiraculously, it now shares its power for nothing in return except one's mere presence.\n\nAntuka will know more. Go with haste, $p. This is wondrous news.", objectives = "Speak to Antuka in Tyrhold.", completion = "Every week, the catalyst will grant you enough power to imbue one piece of equipment.\n\nKeeper Tyr must be watching us. Wherever he is, this is no coincidence." }
