WordHunterWoW_QuestEN[75506] = { title = "Shadowflame Crests", description = "Now that you've gotten a taste of power, the real fun begins.\n\nFlightstones alone will only get you so far. We have also discovered four different tiers of Shadowflame Crests, which are required to empower ever more powerful gear.\n\nFifteen fragments can be combined to make a complete crest of its tier. Like Flightstones, fragments can be found across the Dragon Isles. The more dangerous the activity, the more powerful the fragments.\n\nAnd if you need fragments, visit Spinsoa outside. He can sell some.", objectives = "Visit Spinsoa and create a Shadowflame Crest by combining 15 Shadowflame Crest Fragments from the same tier.", progress = "Have you found enough fragments?", completion = "Perfection. Upgrade specialists will always identify if crests are needed for your upgrade.\n\nSpeaking of power, please take this trinket! I was told to distribute them to Loamm's newcomers as a welcome gift.\n\nWe can utilize the trinket in our next lesson." }
WordHunterWoW_QuestEN[75507] = { title = "Catching Up with Friends", description = "Now that you've learned the fundamentals, you may have an easier time upgrading lower-level gear.\n\nWe can use the Friendship Censer trinket as an example. If you have acquired more powerful trinkets in the past, it will cost us less resources to upgrade this trinket.\n\nYou'll notice that fewer Flightstones will do the job! No crests required.\n\nGo ahead, try upgrading the trinket or a lower-level piece of equipment that you have. If you need another trinket, Innkeeper Floressa sells them.", objectives = "Upgrade the Friendship Censer or an Explorer's level piece of equipment with Flightstones.", progress = "You may wonder when you'd ever utilize this knowledge.\n\nWell, the Friendship Censer is much weaker than what I typically wear. But who doesn't want to be better friends with the niffen? I was able to quickly upgrade the trinket to my own gear's level. In fact, if I had more resources, I could fully achieve its potential to be even more powerful.", completion = "With this knowledge, I bless you to go forth and achieve the power you've always imagined. If you ever need a refresher, speak with me!" }
WordHunterWoW_QuestEN[75511] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[75516] = { title = "Successful Interventions", description = "", objectives = "" }
WordHunterWoW_QuestEN[75517] = { title = "Sneak and Sniff", description = "", objectives = "" }
WordHunterWoW_QuestEN[75518] = { title = "The Body on the Banks", description = "<The state of the corpse of this centaur woman is surprising.\n\nHer clothing is in a style unfamiliar to you, and her skin is emblazoned with intricate tattoos.\n\nHer body is intact, so it seems as though she could not have been dead long... or could she? Conditions here may have led to better preservation.\n\nRoska will want to have a look at this!>", objectives = "Speak to Roska to begin carefully excavating the centaur corpse.", progress = "Nothing like silt, eh <name>? Never know what you'll find!", completion = "Would you look at that! I bet this poor gal has been buried under all that silt for hundreds of years if not more.\n\nBogs and riverbeds like this tend to preserve what's been left in them.\n\nBut now that she's out, we can find out more about who she was and how she got here!" }
WordHunterWoW_QuestEN[75519] = { title = "The Long Hunt", description = "<Dori'thur hovers silently, peering at you with keen, expectant eyes.\n\nWith a taloned foot, the noble owl offers you an imbued crystal. Within that crystal, you sense a message.>", objectives = "Witness the message.", completion = "<Dori'thur blinks knowingly.>" }
WordHunterWoW_QuestEN[75525] = { title = "Secured Shipment Looted", description = "", objectives = "" }
WordHunterWoW_QuestEN[75528] = { title = "A Tester's Guide to Entering Zaralek", description = "Hail, and well met!\n\nWhile the story of Zaralek has yet to unfold, there is plenty to see within the cavern! Make way to Loamm, home of the Niffen.", objectives = "Enter Zaralek Cavern through Iridikron's Gambit.Hail, and well met!\n\nWhile the story of Zaralek has yet to unfold, there is plenty to see within the cavern! Make way to Loamm, home of the Niffen." }
WordHunterWoW_QuestEN[75538] = { title = "Beginning Impositions", description = "Darkest greetings, {race}. Ahem, yes. Yes! Darkest greetings indeed.\n\n<The lanky man seems to suddenly remember where he is.>\n\nOn behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes!\n\nAhem.\n\nShe requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows...\n\n...Madam Shadow.", objectives = "Travel to the Darkmoon Faire.", progress = "Everyone knows the way to the Faire...", completion = "You're... smaller, than I remember." }
WordHunterWoW_QuestEN[75539] = { title = "Some Wicked Things This Way Come", description = "Phineas did well in bringing you to me, {name}. There is much work to be done.\n\nWe'd best get to it!\n\nAs a master of the dark arts, I need you to help me whip these newcomers into shape. Talk to them. They come from many walks of life--all of them unfamiliar with the dark arts.\n\nLearn their wishes. \n\nTheir hopes.\n\nTheir dreams.\n\nThis path we walk can bestow gifts unending and power unimaginable. One just needs to know what one truly desires...", objectives = "Talk to the newly arrived warlocks around the Darkmoon Faire.", progress = "What have you learned, <name>?", completion = "Only one or two pairs of cold feet, hm? \n\n<Madam Shadow chuckles.>\n\nExcellent.\n\nNow that we know who wants to be here, it is time to determine who deserves to be here." }
WordHunterWoW_QuestEN[75540] = { title = "Hermetic Insurance", description = "Ah, the latest group have gathered beneath my wings like chicks to a mother crow. You've done well so far, {name}. They trust you. \n\nI trust you.\n\nThe next step in shepherding these simple souls along in their diabolical journeys is to safeguard them against the void. Against oblivion. Against death.\n\nTake my soulstone and use it to gird the willing... and the damned.", objectives = "Use Madam Shadow's Soulstone on willing initiates in the Darkmoon Faire.", progress = "Is it done?", completion = "Delicious." }
WordHunterWoW_QuestEN[75541] = { title = "Those Who Hesitate", description = "Hm.\n\nThere is one who has been counted amongst our number, but is not here.\n\nThe draenei.\n\n<Madam Shadow inhales.>\n\nI can taste the Light about him. Go, see to it that he rejoins us.\n\nThere is much work to be done.", objectives = "Talk to Initiate Oman in the Darkmoon Faire.", progress = "This view reminds me of... many things.", completion = "Now to appease our mysterious patron..." }
WordHunterWoW_QuestEN[75542] = { title = "Curses & Cultists", description = "The wheat has been separated from the chaff. Now the fun can truly begin.\n\nI have an exciting... field trip... planned for our students. But they are not yet ready. Take my grimoire and have the pandaren, zandalari, and tauren try their hand at curses. \n\nI found some uninvited guests loitering on the edges of our fairground. They should make excellent, if unwilling, test subjects.\n\nOman will have the honor of summoning the group far afield, and I will instruct him as such.", objectives = "Teach the initiates curses from Madam Shadow's grimoire in the Darkmoon Faire.", completion = "It worked! That grimoire of Madam Shadow's really is powerful...\n\nI hope I didn't startle you, <name>." }
WordHunterWoW_QuestEN[75543] = { title = "Last Rites By Accident", description = "<You can hear the faint sound of screaming coming from the other side of the portal.>", objectives = "Go through the Demonic Gateway and help the Initiates.", completion = "The others... their soulstones...\n\nI saw a green flicker in their eyes as they fell, one by one. Like the very essence of their souls were being drawn forth.\n\nThey deserved better." }
WordHunterWoW_QuestEN[75544] = { title = "When Revenge Burns Green", description = "Whatever game this Madam Shadow has been playing, it appears as though we're nearing the end of it.\n\n<Oman grunts in pain.>\n\nFrom what we've heard, it sounds like our next destination is somewhere in the Blasted Lands.  I must rest, but please {name}... go and see this through. Bring Madam Shadow to account. Avenge our fellow warlocks.", objectives = "Confront Madam Shadow in the Blasted Lands.", completion = "Those soulstones... the other warlocks. \n\n<Oman closes his green eyes.>\n\nWhen I chose to walk this path, I knew there would be repercussions. That I would be sacrificing a part of myself. A part of how my people see me. \n\nBut to have your soul torn asunder... for what? Petty revenge?\n\nTruly that is a fate worse than anything I have taken upon myself." }
WordHunterWoW_QuestEN[75569] = { title = "Blacksmith, Black Dragon", description = "The black dragonkin in the north of Zaralek Cavern are said to be fine blacksmiths.\n\nThey're quick to claim it has something do with a \"dominion over the earth\", but I'd like to see them try burrowing like a proper niffen!\n\nStill, you can't argue with the results. Grab a few examples and bring them to Kilnmaster Crubus in Loamm so he can study their techniques.", objectives = "Collect 8 Blackened Plate.", progress = "I wonder if I could use one of their helmets as a tub?", completion = "The craftsmanship is impeccable, but would it kill them to use a color besides black?" }
WordHunterWoW_QuestEN[75573] = { title = "Proclamation Reclamation", description = "You know who likes to hear themselves talk, loves bureaucracy, and enchants their own records? Dragons!\n\nGo poke around in the old black dragon fort north of Loamm. I'm sure they'll be all sort of magic-ish decrees, proclamations, and shopping lists just lying around!\n\nBring whatever you uncover to Scridorsa the Chiseler back in Loamm. I'm sure she'd love something new and heavily enchanted to read!", objectives = "Collect 10 Infused Proclamations.", progress = "Can't do anything simply, can they?", completion = "<Scridorsa flips through the documents.>\n\n\"By my hand...\", \"The will of the Earth-Warder...\", \"At my command...\" Sounds like a dragon, sure enough!\n\nStill, these should make for an interesting study, if not read." }
WordHunterWoW_QuestEN[75575] = { title = "Ballistae Bits", description = "Those djaradin might smell like brutes, but their engineering corps must be top notch to keep churning out ballistae strong enough to threaten a dragon!\n\nNortheast of Loamm there's an ongoing scrap between them and some black dragons. There ought to be lots of spare parts scattered around. Or slightly used, moderately on fire ones, anyway!\n\nHaul them all back to Loamm! A little scorching won't stop our top minds from reverse niffeneering them.", objectives = "Collect 10 Ballistae Bits.", progress = "I wonder what they use for torsion?", completion = "Interesting, that's a lot more bone than I would have expected given the stress involved!" }
WordHunterWoW_QuestEN[75576] = { title = "Grim Guzzler Invasion!", description = "", objectives = "" }
WordHunterWoW_QuestEN[75598] = { title = "Snailed It", description = "Hmm. You ever mount a snail before?\n\nI've trained generations of racing snail champions, but lately I've come across my toughest case yet. Simply put, he's too crokin' big. Straight up barred from competition.\n\nIt's a shame to keep such a prize specimen stuck in a bucket, though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", objectives = "Introduce yourself to Slick.", completion = "I have never been prouder. Y'all snailed it.\n\nNot many have what it takes to enter the fast-paced world of snail racing, but you? You got it. I just know Slick is going to enjoy spending the rest of his snaily life going on adventures with you.\n\n<Briggul sniffles and pats Slick's shell.>\n\nHappy slime trails to you, big guy. Make sure you come back to visit!" }
WordHunterWoW_QuestEN[75600] = { title = "Silk's Silk", description = "We may not have access to all those fancy plant fibers you surface types use up here, but we do have a lot of options I bet you don't!\n\nThe spiders near Loamm make the most interesting smelling silk I ever did sniff. I think it might have something to do with their diet?\n\nIf you round some up, I'm sure Rossmar back in Loamm will be happy to teach you a thing or two about how to use it!", objectives = "Collect 8 Calcisilk Bundles.", progress = "Just follow the bone-y smells!", completion = "Doesn't the calcium give it the best texture?" }
WordHunterWoW_QuestEN[75602] = { title = "Chips off the Old Crystal Block", description = "The crystalline creatures back home are as mysterious as they are stompy.\n\nWhat allows them to move? Are they even really alive? What do they taste like?\n\nBring Fanilly a few samples to start studying. Just not any big enough to step on anyone in Loamm, ok?", objectives = "Collect 10 Living Chips.", progress = "Who knows what we could learn?", completion = "Fascinating, <name>, thank you for your contribution to the art." }
WordHunterWoW_QuestEN[75603] = { title = "Do Rites by Her", description = "This gal has been here for a long, long time. It's a wonder she's in such good condition.\n\nIt's one thing to dig up pottery shards in the mud, but something like this requires more care and expertise than you and I have combined! Maruukai isn't far from here...\n\nWe should tell the centaur about this. They can decide how best they'd like to proceed, eh?\n\nWhile we're at it, I bet some of their expert artisans can tell us about her gear.", objectives = "Consult Storykeeper Jaru, Farrier Rondare, and Tigari Khan for guidance on how to treat the ancient corpse.", progress = "We've got a proper dig now here!", completion = "It doesn't get better than this, <name>. New chapters of history unfolding, whole communities rallying around a find... \n\nThey'll be talking about this dig for years!\n\nMakes all the stomping around in the mud worthwhile, doesn't it?" }
WordHunterWoW_QuestEN[75604] = { title = "Antiquated Antics", description = "Well, there's two factors at play here, eh?\n\nWe should do our due diligence and figure out who this was a statue of. But between you and me? I'm much more interested in learning about the jokesters that turned it into this work of art.\n\nI'm sure there's a historian of the black dragonflight somewhere near Aberrus. And why don't you poke around Loamm to see if there are any stories surrounding this kind of... artistic license.", objectives = "Find experts from both Loamm and the black dragonflight to weigh in on your find.", progress = "<Roska looks pleased with your work.>", completion = "We'll keep up the dig around the tower. \n\nThere's still an awful lot of midden to go through. Even if we don't find something this spectacular again, we've got a lot to learn about the niffen and how they lived before and during the dragons leaving.\n\nBut I think we've done a good day's work for now!" }
WordHunterWoW_QuestEN[75608] = { title = "Titan Trash or Titan Treasure?", description = "The watchers left all sorts of amazing technology just laying around when they went to sleep.\n\nWe could learn so much from their ancient castoffs. Even the least of contraptions are marvels to behold!\n\nIf only there was someone brave, intelligent, and dare I say handsome enough to go retrieve a few examples for our finest niffeneers back in Loamm to examine... sound familiar?", objectives = "Collect 10 Hololithic Gears.", progress = "I wonder if we'll ever truly understand their technology?", completion = "What's a hololithic gear, you ask? I don't know, but I look forward to finding out!" }
WordHunterWoW_QuestEN[75611] = { title = "Glimmerfish Before It's Gone", description = "", objectives = "" }
WordHunterWoW_QuestEN[75612] = { title = "Cascades Calling", description = "", objectives = "" }
WordHunterWoW_QuestEN[75617] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in the Ohn'ahran Plains.", completion = "Honor the Ohn'ahran Plains flame." }
WordHunterWoW_QuestEN[75619] = { title = "Thieving Critters", description = "", objectives = "" }
WordHunterWoW_QuestEN[75620] = { title = "Liars in Light", description = "", objectives = "" }
WordHunterWoW_QuestEN[75621] = { title = "Element Whispers", description = "", objectives = "" }
WordHunterWoW_QuestEN[75622] = { title = "Calling All Competitors!", description = "The Artisan's Consortium has struck a deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can now purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this flier to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", objectives = "Deliver the flier to Calderax in the Gladiator's Refuge of Valdrakken.", completion = "Hm, they sure know how to reach their audience.\n\nHere are your trophies as promised. Use these when crafting your own equipment or submitting Crafting Orders and the gear will be comparable in power to what I offer. It is perfect if you are looking for something highly specific or imbued with a certain embellishment... and are willing to put in some extra work.\n\nQuestions? Take them to the Artisan's Market." }
WordHunterWoW_QuestEN[75624] = { title = "The Champion's Challenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[75625] = { title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", objectives = "Speak with Mizzen at the Stormwind Harbor.", completion = "Hey there, glad you could make it!\n\nYou gotta check out this machine!" }
WordHunterWoW_QuestEN[75626] = { title = "Wanna Play a Game?", description = "<You open a scribbled note.>\n\nHeya pal! The name's Mizzen, and I hear you're pretty good at findin' stuff.\n\nSee, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins.\n\nHow about we meet up and I'll tell you where to find some?", objectives = "Speak with Mizzen in Orgrimmar's Valley of Strength.", completion = "Hey there, glad you could make it!\n\nYou gotta check out this machine!" }
WordHunterWoW_QuestEN[75632] = { title = "A Dislocated Disc", description = "As a gesture of good will, Eternus has pledged her assistance in finding the disc that contains Tyr's memories. The infinites have devices that can aid in divining its location.\n\nTo quote Eternus, \"This is a mess Deios made. It is fair we help clean it up.\"\n\nI feel some responsibility as well after our attempt to wake Tyr with the Silver Scale.\n\nMeet Eternus at Tyrhold. She will brief you on her progress. Perhaps now our old friend will finally join us once more.", objectives = "Meet Eternus in Tyrhold.", completion = "We meet again, <name>. Nozdormu said you would come. I welcome your aid." }
WordHunterWoW_QuestEN[75633] = { title = "We Have the Technology", description = "During our... long discussion about how to find Tyr's disc, Chromie and I agreed that you were the right person to help us, {name}. But finding the location of Tyr's disc could be very dangerous and would likely require more than just your help.\n\nWhile I work here to narrow down what we need to find the disc, Chromie can give you more details.", objectives = "Ask Chromie about the plan to recover Tyr's memory disc.", completion = "It's good to see you again, <name>! I have hope that this time we will finally be able to restore Tyr's memories." }
WordHunterWoW_QuestEN[75634] = { title = "Reforging the Tyr's Guard", description = "After the tomb was destroyed and the Silver Scale failed to bring Tyr back, I made the decision to rededicate my life to Tyr.\n\nAnd I made the even harder decision to leave the past behind and reforge Tyr's Guard.\n\nI had faith Tyr would need me again soon. And, after consulting with the Silver Hand, Koranos and I believe we have found four worthy Tyr's Guard recruits.\n\nCome with me to Brackenhide Hollow, and assist me in their final training. Then we can venture into the timeways to find Tyr's disc.", objectives = "Meet Travard at the Tyr's Guard camp in Brackenhide Hollow.", completion = "Now that you're here, we can get started with my recruits' final trials." }
WordHunterWoW_QuestEN[75635] = { title = "For Tyr!", description = "Did they all complete their trials successfully? Good. I'm sure you played no small part in that.\n\nThere's one final step we need to take before I can formally induct our recruits as full-fledged members of the Tyr's Guard: the Tyr's Guard initiation ceremony. \n\nIt would make me proud if you stood with us on the steps of Tyrhold as I formally reforge the Tyr's Guard. Will you join us?", objectives = "Witness the induction ceremony of the Tyr's Guard on the steps of Tyrhold.", completion = "The Tyr's Guard stands once again. I feel both renewed and... very old. They still have much to learn, and I have much to teach them.\n\nNow, onto the task of recovering Tyr's memories!" }
WordHunterWoW_QuestEN[75636] = { title = "Tyrangulation", description = "The portals are ready. The sooner your team deploys those beacons, the sooner we can get the location of the disc. \n\nHow you deploy your forces is up to you--and Travard.", objectives = "Protect Travard at the Temple of Order.", completion = "Welcome back! Eternus said there was a signal from your beacon, so I assume everything went smoothly?" }
WordHunterWoW_QuestEN[75637] = { title = "The Final Beacon", description = "Valunei and Talthis still aren't back. They must have had trouble with their beacon. We can't find the disc without it, and there's no way to help from here. \n\nWe must lead the Tyr's Guard through their portal to help. Are you ready, {name}?", objectives = "Help the Tyr's Guard activate the Final Beacon.", progress = "We must discover what was happened.", completion = "We're all back in one piece, thank the Light.\n\nNow, hopefully our dragon friends can find that disc!" }
WordHunterWoW_QuestEN[75638] = { title = "Dislocated Disc Located", description = "We were successful, {name}, but we barely made it back from our battle with the Black Empire.\n\nEternus is still divining the location of the disc, and while she does, I'd like to ask a favor.\n\nI have unwavering faith in my recruits, but...\n\nI am worried about Valunei. I would speak to her, but I don't want it to appear as though I think she has failed us. Talk to her and make sure she's all right.\n\nIt may also be a good idea to check in with the rest of Tyr's Guard as well.", objectives = "Check in with the Tyr's Guard.", progress = "I'm worried about my recruits, but maybe I should be worried about myself.\n\nReforming the Tyr's Guard has been a kind of catharsis. But I'm worried that it may be too much so.\n\nI was devastated by the loss of my comrades in the Tyr's Guard... I worry that I may be pushing them too hard.\n\nOr myself. I've been at this a long time, <name>. But to see Tyr alive once more... that gives me purpose.\n\nI just hope wisdom comes with my age, and I do right by my new recruits. And that they all come home.", completion = "I'm glad to hear you were able to speak to her. It sounds like she is ready despite what happened. \n\nA lesser person would have not been able to pick themselves up after that, but Valunei is stronger than many of us realize.\n\nAs soon as Eternus locates the disc, we will be ready." }
WordHunterWoW_QuestEN[75639] = { title = "Fel Suspicions", description = "At the risk of stating the obvious, something very wrong is going on.\n\nI know you feel it too.\n\nMadam Shadow is sending myself and the other initiates to the Altar of Storms, to try our hand at summoning demons. Please, {name}, poke your head around here and see if you can't piece together what she's up to. \n\nI saw her and her servant heading towards the back of the faire... I'm sure she has her guard up. Maybe there's some way you can get close without drawing attention to yourself?", objectives = "Spy on Madam Shadow and Assistant Phineas in the Darkmoon Faire.", completion = "The gate is warm to the touch." }
WordHunterWoW_QuestEN[75640] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in the Azure Span", completion = "Honor the Azure Span flame." }
WordHunterWoW_QuestEN[75641] = { title = "Power Unified", description = "Fortune has favored our exploration, <name>! We have discovered something that may prove useful to you.\n\nIt is half of a Spark of Shadowflame. It's unfortunately just a shard and not powerful on its own, but should you locate the other piece and unite them, the spark could serve as a powerful reagent in your craft work.\n\nFind another Splintered Spark of Shadowflame. Unite both pieces to unlock their full potential.", objectives = "Find another Splintered Spark of Shadowflame.", progress = "Did you find the other half of the spark?", completion = "Excellent! If you find other splintered sparks, combine them to enhance your craft work!" }
WordHunterWoW_QuestEN[75643] = { title = "Orientation: Loamm Niffen", description = "I'm impressed. Elder Honeypelt speaks highly of you--and that's rare!\n\nYour friends Ebyssian and Emberthal admittedly made similar impressions with us after we caught their scent. They told me of your hunt for the fiery monster that's invaded Zaralek from the uplands. A worthy reason to become allies.\n\nBut we'll need a bit more time to discuss it. Why not take a short break to meet with my people. Trade, leisure, travel--there's no shortage of ways to spend your time here in Loamm!", objectives = "Meet the Flight Master in Loamm.", progress = "Smells around every corner, but nothing dangerous!", completion = "Zaralek Cavern will not see the end of these new enemies any time soon, so let us continue getting to know each other with open arms and open snouts.\n\nConsider this your official invitation to stay with us here in Loamm, the great city of smells!" }
WordHunterWoW_QuestEN[75644] = { title = "Six Hundred Feet Under", description = "That was just a taste of the niffen lifestyle. There's still far more to Loamm and even more from Zaralek Cavern. Continue exploring while you pursue the fiery monster, and let its scents continue to amaze you!\n\nFor now, Ebyssian asked that I send you his way. Seems your companions are planning what to do next.", objectives = "Discuss the next plan of action with Ebyssian.", progress = "There is much to discuss.", completion = "Though I still wish you had waited for Emberthal and myself to arrive, I do not believe the outcome would have been any different. This Incarnate is more powerful that we anticipated.\n\nThere is much to consider." }
WordHunterWoW_QuestEN[75645] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Thaldraszus.", completion = "Honor the Thaldraszus flame." }
WordHunterWoW_QuestEN[75647] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in the Forbidden Reach.", completion = "Honor the Forbidden Reach flame." }
WordHunterWoW_QuestEN[75650] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Zaralek Cavern.", completion = "Honor the Zaralek Cavern flame." }
WordHunterWoW_QuestEN[75657] = { title = "Time-Lost Trio", description = "We have a teensy problem I could use your help with. But it's... complicated.\n\nSome time ago, King Varian Wrynn was in a gladiator trio with Broll Bearmantle and Valeera Sanguinar. Those three just showed up in this 'Field of Ferocity' place and they're not only taking on all challengers, they're beating them too! They won't return through our portals until they lose.\n\nDo you think you could find some friends and defeat them? We'll be able to convince them to go back if you can, I'm sure of it!", objectives = "Defeat Valeera, Broll, and Lo'Gosh.", progress = "You need to speak with Gurgthock to start the round, then defeat the time-lost gladiators.", completion = "Huh. I didn't know we had a group like that on the schedule. Or sparkly gold pyrotechnics.\n\nBut, I guess you won, so here." }
WordHunterWoW_QuestEN[75660] = { title = "Ending Their Watch", description = "", objectives = "" }
WordHunterWoW_QuestEN[75661] = { title = "Curative Crystalline Collection", description = "", objectives = "" }
WordHunterWoW_QuestEN[75662] = { title = "A Race to the Finish", description = "You look like someone that enjoys a good snail race! \n\nAnd what makes a snail race good you ask? Each snail must have a chance to win! \n\nAnd sometimes the snails might need a little bit of help. \n\nIf you grab a bag of treats from the chef and toss it in their path that'll get them moving. \n\nHow about we give Bashful a nudge to victory?", objectives = "Help Bashful win a race.", progress = "Has your snail won the race?", completion = "That was a great victory. I think you should be Bashful's new trainer!" }
WordHunterWoW_QuestEN[75663] = { title = "Restless Torment", description = "", objectives = "" }
WordHunterWoW_QuestEN[75664] = { title = "Discordant Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[75665] = { title = "A Worthy Ally: Loamm Niffen", description = "Djaradin, dracthyr, and dragons! Oh my!  You can't help but smell the danger in these here caverns. We sure could use some armed assistance.\n\nYou scratch my back, and I'll make sure the kith scratch yours! We got loads of good stuff... for the right clientele.\n\nHow about it? Get out there and bury the competition?", objectives = "Aid the niffen and their allies throughout Zaralek Cavern.", progress = "Are our enemies six feet under?", completion = "You're that much closer to getting a whiff of the good stuff. \n\nThanks, champ." }
