WordHunterWoW_QuestEN[75694] = { title = "Aberrus, the Shadowed Crucible: Sarkareth", description = "I have no interest in following my brothers within Aberrus, but I continue to care for their safety. Neltharion fell so deeply into madness that his secret stronghold is no doubt filled with any number of unspeakable dangers.\n\nGo with them, {name}. Stand with them. They will need your support in what is to come.", objectives = "Enter Aberrus, the Shadowed Crucible, and defeat Sarkareth.", progress = "Aberrus holds mysteries and dangers alike. They must be dealt with, before any of them fall into the wrong hands.", completion = "I never imagined that Sarkareth would have gone to such lengths to seize power.\n\nThank you, <name>." }
