WordHunterWoW_QuestEN[75706] = { title = "A Race to the Finish", description = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win.\n\nYou can help a snail win by giving it treats. Watch how fast it makes them go!\n\nGrab a bag of treats and toss them in the path of the snails. See if you can get Tricky to win!", objectives = "Help Tricky win a race.", progress = "Has your snail won the race?", completion = "That was a great victory. I think you should be Tricky's new trainer!" }
WordHunterWoW_QuestEN[75707] = { title = "A Race to the Finish", description = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win.\n\nYou can help a snail win by giving it treats. Watch how fast it makes them go!\n\nGrab a bag of treats and toss them in the path of the snails. See if you can get Brulee to win!", objectives = "Help Brulee win a race.", progress = "Has your snail won the race?", completion = "That was a great victory. I think you should be Brulee's new trainer!" }
WordHunterWoW_QuestEN[75709] = { title = "Find a Rumble Coin", description = "To use this game machine, you need a Rumble Coin.\n\nThere are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later.\n\nI stashed one coin here at the docks. If you find it, it's all yours, pal.\n\nInsert that Rumble Coin into the Rumble machine and watch the fun begin!", objectives = "Find a Rumble Coin in Stormwind Harbor and insert it into the Warcraft Rumble machine.", progress = "<The Warcraft Rumble machine stands before you. A small sign reads:>\n\nInsert Rumble Coin to play.", completion = "<As you insert your coin, the fun little machine rumbles and jingles.\n\nYou got a prize!>" }
WordHunterWoW_QuestEN[75711] = { title = "Find a Rumble Coin", description = "To use this game machine, you need a Rumble Coin.\n\nThere are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later.\n\nI stashed one coin over in the inn. If you find it, it's all yours, pal.\n\nInsert that Rumble Coin into the Rumble machine and watch the fun begin!", objectives = "Find a Rumble Coin in the Broken Tusk and insert it into the Warcraft Rumble machine.", progress = "<The Warcraft Rumble machine stands before you. A small sign reads:>\n\nInsert Rumble Coin to play.", completion = "<As you insert your coin, the fun little machine rumbles and jingles.\n\nYou got a prize!>" }
WordHunterWoW_QuestEN[75712] = { title = "Warcraft Rumble Minis: New Look!", description = "<You find a message etched into the foil.>\n\nThis Rumble Foil can be used at a Warcraft Rumble machine. Go and get a new look for one of your minis!", objectives = "Go to the Warcraft Rumble machine in Stormwind Harbor.", completion = "<The Warcraft Rumble machine has a hatch. It's the perfect size to insert a miniature toy and a Rumble Foil.>" }
WordHunterWoW_QuestEN[75713] = { title = "Warcraft Rumble Minis: New Look!", description = "<You find a message etched into the foil.>\n\nThis Rumble Foil can be used at a Warcraft Rumble machine. Go and get a new look for one of your minis!", objectives = "Go to the Warcraft Rumble machine in Orgrimmar's Valley of Strength.", completion = "<The Warcraft Rumble machine has a hatch. It's the perfect size to insert a miniature toy and a Rumble Foil.>" }
WordHunterWoW_QuestEN[75714] = { title = "A Trainee's Test [DNT]", description = "It is time for the trainee to learn how to edit text!\n\nThere are multiple places where text exists.\n\nYou should be aware of all of them.\n\nBeware the red text!", objectives = "This is the text that tells the player what to do and where to go." }
WordHunterWoW_QuestEN[75719] = { title = "[DNT] Test Quest", description = "Hi, I'm a quest! A quest made to test with!", objectives = "" }
WordHunterWoW_QuestEN[75720] = { title = "Care to Barter?", description = "Hey, Uplander!\n\nI hear you like helping. Maybe you could help me out? \n\nI need some packages sent to Valdrakken. If you don't peek and don't ask, I can make it worthwhile. \n\nStop by when you're in Loamm. We can work out a deal!\n\nYour new friend, Ponzo.", objectives = "Talk to Ponzo in Loamm.", completion = "I can smell my letter on you. Ready to help?" }
WordHunterWoW_QuestEN[75721] = { title = "Bartering 101", description = "So here's what I need you to do. \n\nA friend of mine, Kayann, went all the way up to Valdrakken. He's expecting a delivery from me. Can you get it to him? \n\nNo questions, though. Don't look, don't smell, don't taste. This is for Kayann's nose only!\n\nIf that's all right with you, I'll send you on your way--with my thanks, of course!", objectives = "Deliver Ponzo's box to Kayann in Valdrakken.", completion = "I know a Ponzo box when I smell a Ponzo box!\n\nThanks for bringing it up--quite the trip! Here's something Ponzo will love to trade for." }
WordHunterWoW_QuestEN[75722] = { title = "Bag of Gold", description = "Hello, {name}! \n\nI heard you've been helping us out! Good deeds should be rewarded--and I've got something special for you! Why don't you meet me in Loamm?\n\nKeep up the good work, \n\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "You'll always have our thanks!" }
WordHunterWoW_QuestEN[75723] = { title = "Cavern Drakewatching", description = "Well hey there, Uplander!\n\nWord is, you've been helping us out a lot! We got a little something for you in return. See me in Loamm and I'll hand it over!\n\nBest, \nHarlowe Marl", objectives = "Talk to Harlowe Marl in Loamm.", completion = "We're lucky to have you around!" }
WordHunterWoW_QuestEN[75724] = { title = "Like the Niffen Do", description = "Hello there, {name}!\n\nWe want to thank you for all the help you've given us. It's only right! \n\nMeet me in Loamm and I'll teach you to dig like we niffen do!\n\nSincerely, \nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "Just put these mitts on, get them in the dirt, open your snout and boom!\n\nLoamm can be smelled from anywhere in Zaralek Cavern. \n\nThe secret's in the claws! It's always been in the claws!" }
WordHunterWoW_QuestEN[75725] = { title = "Off to the Track", description = "Hey Champ! \n\nWe got a fresh golden opportunity for you. Snail racing! One of the most dynamic sports in the games! \n\nPonzo said you'd be interested. Called you a real go-getter!\n\nSo go! Get to the track in Glimmerogg! \n\nSee ya there, \nBriggul", objectives = "Talk to Briggul in Glimmerogg.", completion = "You're here! Now all we need to do is... train our snail!" }
WordHunterWoW_QuestEN[75726] = { title = "Sweaty Armor", description = "Well hey there, friend! \n\nWord is starting to spread about your continued support! We found some armor that might help you out, in thanks for all your troubles. \n\nMake sure to swing by Loamm so we can get you situated. \n\nBest, \nHarlowe Marl", objectives = "Talk to Harlowe Marl in Loamm.Well hey there, friend! \n\nWord is starting to spread about your continued support! We found some armor that might help you out, in thanks for all your troubles. \n\nMake sure to swing by Loamm so we can get you situated. \n\nBest, \nHarlowe Marl" }
WordHunterWoW_QuestEN[75727] = { title = "The Smelliest Tabard", description = "Greetings, {name}!\n\nYou just keep doing us amazing favors, don't you? Come on back to Loamm for an extra special reward!\n\nSincerely,\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "Here it is, handcrafted and handscented!" }
WordHunterWoW_QuestEN[75728] = { title = "Bartering Boulders", description = "Oh hey, Uplander! I could use your help again. \n\nI like your battering style. But you know these bricks? They're useless! Boulders are where it's at! \n\nCome see me in Loamm, and I'll give you all the details.\n\nPonzo", objectives = "Talk to Ponzo in Loamm.", completion = "I hope you've been working out. These aren't light at all!" }
WordHunterWoW_QuestEN[75729] = { title = "Attune to the Observer", description = "Can you believe this used to be an observatory? Our records indicate that the dragonkin here were mapping heavenly bodies in an attempt to predict the future.\n\nHow do you think they did it?\n\nI'm picking up a partial signature that matches the time window we're shooting for. Put on the Technoscryers and try to pinpoint the sources so we can dial it in.", objectives = "Technoscry for the three attunement relics.", progress = "Without those attunement relics we won't be able to solve this mystery, <name>.", completion = "Ah ha! Give me your scryers, so I can calibrate them." }
WordHunterWoW_QuestEN[75730] = { title = "Slitherdrake Watching", description = "Well hello there!\n\nWord around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over!\n\nBest,\nHarlowe Marl", objectives = "Talk to Harlowe Marl in Loamm.", completion = "We're lucky to have you around!" }
WordHunterWoW_QuestEN[75731] = { title = "Scented Boots", description = "Well hello there!\n\nWord gets around of your continued support. We've found some armor that you may be able to use. Come meet me in Loamm and we'll see if it's useful!\n\nBest,\nHarlowe Marl", objectives = "Talk to Harlowe Marl in Loamm.", completion = "We're lucky to have ya around." }
WordHunterWoW_QuestEN[75741] = { title = "Bundle of Boulders", description = "Hey Uplander!\n\nI heard you've been telling people I've been mean to you. \n\nI haven't, but they told me to be nicer to you because all you've done for us. \n\nTaken advantage of? More like giving you some honest work!\n\nTo make you and the others happy, I'll give you some boulders. \n\nSee me in Loamm, \nPonzo", objectives = "Talk to Ponzo in Loamm.", completion = "Make sure to mention to Mimuup that I was nice to you, you hear?" }
WordHunterWoW_QuestEN[75742] = { title = "Drake Helms", description = "Howdy!\n\nWord gets around of your continued support. \n\nWe got a little something for ya. Meet me in Loamm so I can get it to ya!\n\nBest,\nHarlowe Marl", objectives = "Talk to Harlowe Marl in Loamm.", completion = "We're lucky to have ya around." }
WordHunterWoW_QuestEN[75744] = { title = "A Token of Our Gratitude", description = "Greetings!\n\nWith all the help you've given us, we've decided it's only fair to return the favor.\n\nMeet me in Loamm. We have a reward we're eager to give you.\n\nSincerely,\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "Thanks for everything, Uplander!" }
WordHunterWoW_QuestEN[75750] = { title = "Are They Not Beautiful?", description = "", objectives = "Defeat Shinmura in a Pet Battle" }
WordHunterWoW_QuestEN[75765] = { title = "Liquid Art", description = "<A clay pot filled with... mud?\n\nIt appears to be niffen in origin. Perhaps a resident of Loamm is looking for it!>", objectives = "Return the Dripping Clay Pot to its owner in Loamm.", progress = "Oh, is that...?", completion = "You found my favorite slip pot!\n\nI can make slip in any pot, but this is one of the first pots I made of special sediments I dug myself.\n\nIt's sentimental ... AND sedimental!" }
WordHunterWoW_QuestEN[75766] = { title = "Ruby in the Rough", description = "<A beautiful ruby set in fine gold sits nestled in a box of draconic origin.\n\nThe jewelcrafter in Loamm would love to take a look at this.>", objectives = "Deliver the Shimmering Draconic Gem to Fanilly in Loamm.", progress = "It's SO shiny!!", completion = "This is beautiful! Did the dragons make this? It's so red and sparkly!\n\nThank you, <name>!" }
WordHunterWoW_QuestEN[75767] = { title = "Good Time Boy", description = "<A very wet gorloc totem rests on the cave floor. How did this even get here?\n\nThe niffen love stuff like this. Maybe someone in Loamm will take it off your hands.>", objectives = "Find a new home for the Soaked Totem in Loamm.", progress = "I've needed a backup dancer!", completion = "<The niffen gives the totem a huge sniff.>\n\nHe smells like fish! Excellent! \n\nHe'll make an excellent bouncer for my shows. I think I'll call him... Whistlee!" }
WordHunterWoW_QuestEN[75768] = { title = "Lucky Ducky", description = "<You find a small toy duckling.\n\nIt reminds you just a little of Loamm's swallows. Maybe Cinnam will like this?>", objectives = "Give the Feathered Friend to Cinnam in Loamm.", progress = "This is for me?", completion = "Wow! Thank you, <name>.\n\nSeeing as I'm the new Head Swallowsminder, I've been in need of an apprentice!" }
WordHunterWoW_QuestEN[75769] = { title = "Drawing a Blank", description = "<A discarded painting covered in dust rests on the cave floor.\n\nMaybe someone in Loamm could make use of this?>", objectives = "Give the Stretched Canvas to a niffen in Loamm.", progress = "How did you know I wanted to try my nose at scent-painting?", completion = "A brand-new canvas! This will be perfect to practice my scent-painting on.\n\nRight now it smells so... blank! Thanks!" }
WordHunterWoW_QuestEN[75770] = { title = "A Glass of Bubbly", description = "<You find a glowing blue potion of indeterminate origin.\n\nMaybe the Loamm alchemist will want to take a look?>", objectives = "Take the Bubbling Elixir to Mistie in Loamm.", progress = "Hmm... I'll need to run some analysis!", completion = "This is most intriguing.\n\nI'll have to get the best noses in Loamm on the case so we can identify just what this is.\n\nThank you, <name>!" }
WordHunterWoW_QuestEN[75771] = { title = "Incense Replay", description = "<You find some incense that smells familiar, but you can't quite place it.\n\nCitros will definitely want to take a sniff.>", objectives = "Take the Mysterious Incense to Citros in Loamm.", progress = "Boy howdy! That's some mighty strong incense!", completion = "This doesn't smell like niffen!\n\nIt doesn't smell bad, though, not at all!\n\nIf you don't mind, could I take a closer sniff?" }
WordHunterWoW_QuestEN[75772] = { title = "Flask Manager", description = "<A small leather-wrapped flask sits on a shelf in the cave.\n\nSomeone might be missing this.>", objectives = "Find the owner of the leather-wrapped flask.", progress = "Well it's not mine, but I'll take it off your hands!", completion = "There's no way this belonged to someone in Loamm. I've never seen leather quite like this before.\n\nIf you don't mind me asking, could I take a closer sniff at this? I might be able to apply some of these techniques!" }
WordHunterWoW_QuestEN[75773] = { title = "Little Blank Book", description = "<You find a book filled with Draconic text and not much else.\n\nMaybe someone in Loamm could help you decipher it?>", objectives = "Bring the book back to Loamm.", progress = "What do you mean, read it? It's blank, silly!", completion = "There's no writing in here! It just smells like blank paper!\n\nI can't read it if there's nothing to smell, Uplander. \n\nStill, it was nice of you to bring me a blank notebook." }
