WordHunterWoW_QuestEN[75985] = { title = "Rest Well, Warrior", description = "Shalkeel deserves to be seen off properly.\n\nI want to dress his burial area and say a few words. I know your time is precious, but would you take the shovel and bury his ashes while I perform the rites?", objectives = "Assist Khasar with Shalkeel's burial.", progress = "If I were able to handle his ashes, I'd have poured them out over the stream he and I played in when we were children.", completion = "I wish I could compensate you for this act, but I have no diplomatic medals or legendary weapons to bestow, <name>. \n\nJust know that I... I could not have shouldered the weight of this day alone. A heart hollowed by loss takes time to fill again.\n\nBe well. And thank you." }
WordHunterWoW_QuestEN[75986] = { title = "Feats Per Minute", description = "Alright, one last problem to help solve. Succeed at this and we'll surely have earned an audience with Tempo!\n\nThe investigators discovered another Time Slime. A much larger, powerful Time Slime. \n\nWe've come to call it Time Slime Prime.\n\nIts temporal energies are greatly accelerated, making it especially deadly. I recommend using the metronographer several times to slow it back down before engaging in combat.", objectives = "Re-synchronize and defeat the Time Slime Prime.", completion = "Ah, there you are. Thank you for your assistance in our time-tidying efforts. \n\nNow I have to a chance to speak with Pedgi himself! Truly, what an honor. It was so difficult holding myself back when he first approached me. But now I have plenty of time to speak with him." }
WordHunterWoW_QuestEN[75987] = { title = "Woolomancer", description = "Somehow, Jaina Proudmoore has found a magic wand. Not our Jaina, of course, but her childhood self. She is far too young to have access to such power.\n\nWe need you to help clean up the mess she's made and confiscate that wand.", objectives = "Dispel 8 Polymorphed Creatures and confiscate Jaina's Wand of Mass Polymorph.", progress = "Jaina must not practice magic until she is old enough to handle it responsibly. I trust you to put a stop to this before the situation becomes dire.", completion = "Thank you for calming that chaos. I shudder to think what would happen if she grew up with such... tendencies." }
WordHunterWoW_QuestEN[75988] = { title = "Lucky Hearthstone Card", description = "I was playing Hearthstone with my father when I somehow ended up here. Then some dragon whelps flew off with my lucky card to add it to their... card tornado?\n\nThen all the adults started saying I need to go home. But I can't leave without my lucky card!\n\nCan you please help me? I promise I'll go home if you bring it back for me!", objectives = "Kill the Enchanted Card Swarm and retrieve Anduin's Lucky Hearthstone Card.", progress = "I feel a little better. Bob gave me some juice. But I still don't know what's going on.\n\nWhere is this place? How did I get here?", completion = "You actually got my lucky card back? Thank you, thank you, thank you <name>!\n\nI'll remember this forever. I'm ready to go home now." }
WordHunterWoW_QuestEN[75989] = { title = "The Black Prince Parade", description = "Five separate portals opened up here at the same time, and the same person stepped out of each one.\n\nNow we have an inn full of Wrathions. All different ages, dealing with different things in their own lives, and very eager to blame each other for their problems.\n\nLet's get them all back to their proper times before they cause too much trouble.", objectives = "Send each Wrathion back to his time through his temporal portal.", progress = "All this commotion is bad for business.", completion = "Glad that's taken care of. Imagine if our Wrathion had stopped by! I don't think my inn could have handled SIX of them." }
WordHunterWoW_QuestEN[75990] = { title = "Star-Crossed Lovers", description = "We found a time disruption long, long ago. Someone helped Illidan charm Tyrande, dooming us all to the Burning Legion!\n\nMalfurion is so distraught he can't even sleep. He has no idea how to win her back.\n\nWe need you to help him out before the timeline is ruined.", objectives = "Help Malfurion gain Tyrande's affection in Val'sharah.", progress = "As painful as it can be, heartbreak can be essential for making us who we are. Even if who are isn't always... nice.", completion = "If only we could've let Illidan have his happily ever after with Tyrande, at least for a little while longer. I always thought those two were really cute together!\n\nBut we all have our role to play to make sure events flow smoothly." }
WordHunterWoW_QuestEN[75991] = { title = "What Could Have Been", description = "A mysterious stranger showed up here a bit ago through one of those time portals. \n\nSaid there's a threat nearby they need your help with. Some kind of cloaking device. Though you might not like what you see once it's disabled.\n\nIn fact, you may not particularly like this stranger, for that matter.", objectives = "Help an alternate version of yourself defeat a mutual foe.", progress = "I know it must be hard to see yourself like this. At least you're on the same side for this one.", completion = "Oh, good. You both made it back alright. Glad to see you managed to set aside your differences." }
WordHunterWoW_QuestEN[75996] = { title = "Your Weight in Gold", description = "", objectives = "" }
WordHunterWoW_QuestEN[75998] = { title = "Crispety Crunchety", description = "<You've seen this kind of beetle near the stables in Loamm. Maybe the stable master will know more about them?>", objectives = "Bring the Crunchy Beetle to Vanndual in Loamm.", progress = "A cherry beetle!", completion = "Cherry beetles are Gary's favorite snack, aren't they Gar-Bear?\n\n<Gary wiggles his antennae.>\n\nIf you find more of these, be sure to bring them by!" }
WordHunterWoW_QuestEN[76004] = { title = "Deep Cuts", description = "<You find a discarded deepflayer claw. You've seen some niffen wield these as weapons.>", objectives = "Bring 1 Deepflayer Claw to Kilnmaster Crubus in Loamm.", progress = "Be careful, those are sharp.", completion = "These claws are the perfect size for weapons for us--they're just hard to come by.\n\nIf you find any more, I'll take 'em off your hands!" }
