WordHunterWoW_QuestEN[76025] = { title = "Dragon Isles Supplies", description = "Well hello there, $p! \n\nI heard you've been helping us out. How about you meet me in Loamm, so we get you a reward? \n\nKeep up the good work, \n\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "We won't forget what you've done for us!" }
WordHunterWoW_QuestEN[76026] = { title = "Surveying the Tower", description = "Get a load of those rock formations! Surveying doesn't get much better than this.\n\nThis tower has been here for ages. The black dragonflight used it for some seriously dark stuff, but that's not why we're here. After the dragons left, a troupe of niffen bandits took shelter in the ruins and robbed the place blind. But they left a bunch of trash everywhere.\n\nImagine what we could learn about the niffen from that trash once we get digging!", objectives = "Speak with Roska to start the dig, then excavate artifacts from around the tower.", completion = "<Roska lets out an uproarious bout of laughter.>\n\nOh, now that one's got to have some kind of crazy story behind it!" }
WordHunterWoW_QuestEN[76027] = { title = "Flapping and Screaming", description = "", objectives = "" }
WordHunterWoW_QuestEN[76028] = { title = "Dragon Isles Supplies", description = "Hello there, $p! \n\nI hear you've been helping us out! Why don't you meet me in Loamm so we get you a reward?\n\nKeep up the good work, \n\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "Thanks so much for all of your help!" }
WordHunterWoW_QuestEN[76029] = { title = "Dragon Isles Supplies", description = "Hello there, $p! \n\nI hear you've been helping us out. Why don't you meet me in Loamm so we get you a reward?\n\nKeep up the good work, \n\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "Thanks so much for all your help around here!" }
WordHunterWoW_QuestEN[76030] = { title = "Airborne Winding", description = "Well hello there!\n\nWord around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over!\n\nBest,\nHarlowe Marl", objectives = "Talk to Harlowe Marl in Loamm.", completion = "We're lucky to have you around!" }
WordHunterWoW_QuestEN[76031] = { title = "Dragon Isles Supplies", description = "Greetings $p! \n\nThank you for helping us! Meet me in Loamm so we get you a reward. \n\nKeep up the good work, \n\nMimuup", objectives = "Talk to Mimuup in Loamm.", completion = "Honestly, we're forever grateful. Thank you!" }
WordHunterWoW_QuestEN[76032] = { title = "Hidden in the Midden", description = "<This dragon statue is similar to others found in the region but has been covered in paint.\n\nGoogly eyes, stink lines, whiskers, and all manner of other rude drawings decorate the otherwise-imposing stone. The paint looks old and is flaking in places but is not as old as the statue itself.\n\nRoska will want to have a look at this!>", objectives = "Carefully excavate the defaced dragon statue.", progress = "Nothing like volcanic rock, eh <name>? Never know what you'll find!", completion = "I'll tell you what, these niffen bandits had a sense of humor!" }
