WordHunterWoW_QuestEN[76101] = { title = "Tougher Down Under", description = "Quite a few uplanders have arrived since the cavern was split clean open! \n\nA friendly winged-one by the name of Vaskarn has been particularly helpful to us. She's made the guard's armor tougher and the monster hunter's weapons stronger.\n\nShe's going to be plenty valuable if you plan on taking down more giant beasties here in Zaralek!", objectives = "Speak with Vaskarn.", completion = "Got quite the gear on you! Shall we see what we can make of it?" }
WordHunterWoW_QuestEN[76103] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", progress = "Did you collect this month's tender?", completion = "Hope ye like this month's collection of new and exotic wares, <name>." }
