WordHunterWoW_QuestEN[76108] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", completion = "Hope ye like this month's collection of new and exotic wares, <name>." }
WordHunterWoW_QuestEN[76112] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", progress = "Did you collect this month's tender?", completion = "Hope ya like this month's collection of new and exotic wares, <name>." }
WordHunterWoW_QuestEN[76113] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", completion = "Hope ye like this month's collection of new and exotic wares, <name>." }
WordHunterWoW_QuestEN[76114] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", progress = "Did you collect this month's tender?", completion = "Hope ya like this month's collection of new and exotic wares, <name>." }
WordHunterWoW_QuestEN[76122] = { title = "Fighting is its Own Reward", description = "Ah, <name>. It's so good to see you.\n\nTheldren and I have learned much thanks to your efforts. But there's always something lurking around the corner that's trying to disrupt the natural order of the Dragon Isles.\n\nI need to ask you to gather your friends and continue to stop those that would try to harm us and our way of life here on the Isles.", objectives = "Complete 5 Dragonflight dungeons on Heroic difficulty.", progress = "I'm thankful for our conversations, but we have work to do.", completion = "Thank you very much, <name>!\n\nYou continue to inspire us all." }
WordHunterWoW_QuestEN[76140] = { title = "Dawn of the Infinite", description = "My vision is hazy, but there is no mistaking what I saw. A dark alliance opposes the bronze dragonflight. One I do not know if I shall be able to overcome...\n\nI ask you to meet me in Eon's Fringe, {name}. We will speak more of this threat there. If there is any who I would entrust with safeguarding our future, it is you.", objectives = "Meet Nozdormu at Eon's Fringe in Thaldraszus.", completion = "Yes, it is I! Chromie from the future! Nice to meet you. Again.\n\nNow, I can't talk too much about when I'm from or why I'm here. Protecting the timeways and all that, you understand. But I know exactly what's going to happen and exactly how to stop it!" }
WordHunterWoW_QuestEN[76141] = { title = "Align in the Sand", description = "So, the timeways, yeah? They're VERY misaligned. And you know how we bronzes hate that! So we need to realign time with these temporal hourglasses. Just plop them down throughout Eon's Fringe.\n\nBut you know me, always needing to help! So I'll be placing another hourglass nearby. Meet me there when you're all done.", objectives = "Place the Temporal Hourglasses throughout the Shifting Sands in Thaldraszus.", progress = "I never thought you would be the one making a mess of the timeways! Usually you're the one helping us get out of trouble, not in it.", completion = "<Chromie listens to your explanation of what you're doing, her eyes wide.>\n\nMe? From the future? Why, she's one of my top three people to trust! \n\nBut it doesn't make sense. Why would she want you to distort the timeways to help Nozdormu? Seems like it would just give him a headache." }
WordHunterWoW_QuestEN[76142] = { title = "On Borrowed Time", description = "I need you to fetch me some time-lost essence. The creatures around here are filled to the brim with the stuff. \n\nSnuff them out and then use this epoch extractor to collect their essence. We'll make good use of it for our next step!\n\nAnd yes, this is going to be a multi-step process. You know how crazy these time shenanigans get!", objectives = "Extract Time-Lost Essence from slain Time-Lost creatures in the Shifting Sands.", progress = "What's this? Time-lost essence? An epoch... extractor?", completion = "Not sure what this all is, but I suppose I'll find some use for it. Best to not let it go to waste." }
WordHunterWoW_QuestEN[76143] = { title = "Chro-me?", description = "One result of your \"time realignment\" is that it seems to have summoned... me? Well, alternate timeline versions of me. \n\nI've never seen so many Chromies in one place! And while they all may be cute, they're playing havoc on the local timeways.\n\nWe need to trap them to synchronize their time signatures. Maybe then they'll be able to tell us what's going on!", objectives = "Trap Alternate Chromies in time stasis.", progress = "I know it's not very polite to trap a fellow Chromie, but we need to synchronize their time signatures as soon as we can! \n\nI'm sure they'll all understand. I know I would! I think?", completion = "<Chromie listens to your report about what the alternate Chromies told you, her eyes growing wider.>\n\nOh no. We've been tricked! That Chromie from the future isn't a future Chromie at all. She's an alternate timeline me, just like the rest of the Chromies running around! \n\nWhy would she lie to you?" }
WordHunterWoW_QuestEN[76144] = { title = "Morchie Mayhem", description = "We need to get to the bottom of this \"future Chromie\" business. Just where is that dragon? She needs to explain herself!\n\nLet's start by inspecting one of her temporal hourglasses. Maybe that will give us a clue.", objectives = "Investigate the false Future Chromie.", progress = "Oh, that Morchie! I've never met such a tricky, nasty Chromie in all my life.", completion = "Well, at least we stopped Morchie's accomplice. Those infinite dragons are always causing all sorts of trouble.\n\nBut we can't rest until Morchie herself is captured and sent packing back to her OWN crummy timeline!" }
WordHunterWoW_QuestEN[76145] = { title = "Who's That Chromie?", description = "Morchie didn't just teleport herself away, she took all the other Chromies with her! I have a bad feeling about why...\n\nWe have to follow and capture her. And question her! I want to know what she's up to.", objectives = "Capture Morchie and question her.", completion = "We can't give up now! There's still time to save the temple and beat those infinites once and for all. We can't let them control the true timeline.\n\nAnd I certainly will not let them turn Nozdormu into that nasty Murozond." }
WordHunterWoW_QuestEN[76146] = { title = "Dawn of the Infinite: Chrono-Lord Deios", description = "Chrono-Lord Deios must be behind this all. As the leader of the infinites, he's sure to have led this invasion. I bet Morchie is working for him too.\n\nLet's head into the Bronze Temple! We need to stop Deios before he ruins the true timeline.", objectives = "Defeat Chrono-Lord Deios.", completion = "It is all thanks to you, <name>. You have saved us from the infinite's terrible dawn.\n\nBut, even more so, you have saved me from a fate that I thought was all but inevitable. You have my eternal gratitude." }
WordHunterWoW_QuestEN[76147] = { title = "Rewind and Reconcile", description = "<You sense powerful time energy emanating from the relic you retrieved after your fight with Chrono-Lord Deios. It appears to have an engraving of two arrows pointing to the left. You should show it to Nozdormu.>", objectives = "Give the Time Relic to Nozdormu at Temporal Conflux in Thaldraszus.", progress = "I sense you have a powerful relic in your possession. Would you allow me to examine it?", completion = "Chronormu mentioned that she found a time relic after your fight with Morchie. That device forced time to move quickly forward. \n\nIt seems this relic is of a similar power, only it can rewind the threads of time, returning one to an earlier point.\n\nI shall safeguard it, <name>. We would not want such a device to fall into the wrong hands." }
WordHunterWoW_QuestEN[76155] = { title = "A Wolf Among Sheep", description = "Thank you for indulging me. \n\nBut I do not want to appear unappreciative of our new... mentor. Do me a favor--go and fill Madam Shadow's soulstone by some other means. Far be it for us to test our teacher, but she has yet to earn my trust.", objectives = "Help Oman fill Madam Shadow's soulstone on Darkmoon Island.", progress = "Yes?", completion = "Ah, the prodigal <class> returneth." }
WordHunterWoW_QuestEN[76158] = { title = "Temporal Gossamer", description = "The Temporal Gossamer takes shape in the form of delicate, silken strands that appear to strengthen when near an Evoker's Ancient Memories.\n\nAssisting the Evoker in finding Temporal Vestigials seems to empower the resolve of these webs, allowing them to bond closely with the Ancient Memories.", objectives = "Strengthen the Temporal Gossemer from group content throughout the Dragon Isles. \n\nThe Gossamer will only strengthen when in a party and near a holder of Ancient Memories.", completion = "Thank you for assisting. Allow me to complete the binding of these temporal strands." }
WordHunterWoW_QuestEN[76159] = { title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", completion = "Hope ye like this month's collection of new and exotic wares, <name>." }
WordHunterWoW_QuestEN[76161] = { title = "Conversation Testing [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[76162] = { title = "Missing Mojo", description = "I was practicing me magic and suddenly I found m'self here. Next thing I know, me mojo had run off!\n\nIt can't have gone far. Would you look for it? I think I need a drink.", objectives = "Recover Vol'jin's missing Mojo.", progress = "Did ya find me mojo?", completion = "Thank you for the help." }
WordHunterWoW_QuestEN[76163] = { title = "A Lighter Shade of Fel", description = "Dear {name},\n\nGreetings. I have taken some time and collected my thoughts after our encounter with Lord Banehollow. \n\nI have also sought those who have similarly survived his dark plan, and have gathered them to me in Booty Bay so that we can decide on a way forward.\n\nWe would ask that you meet us there.\n\nDarkest regards,\n\nPh'el Oman", objectives = "Meet with Oman in Booty Bay.", completion = "I'm glad you came, <race>." }
WordHunterWoW_QuestEN[76164] = { title = "Bovan's Last Hope", description = "If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot.\n\nWe still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work.\n\nGo to the Ohn'iri Springs and look for Boku. I'm sure he will help us.\n\nBaine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.", objectives = "Find Boku at the Ohn'iri Springs.If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot.\n\nWe still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work.\n\nGo to the Ohn'iri Springs and look for Boku. I'm sure he will help us.\n\nBaine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[76167] = { title = "A Place of Refuge", description = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n{name}, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.", objectives = "Meet Baine and Tomul at Toghusuq Village.Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n<name>, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[76168] = { title = "A Place of Refuge", description = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n{name}, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.", objectives = "Meet Baine and Tomul at Toghusuq Village.Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n<name>, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[76169] = { title = "Glow in the Dark", description = "Codswallop! Peevish has run off again. He is assigned to this post but is never here!\n\nI heard him screaming from the nearby cave. He must have tried to hide in there.\n\nTake my torch and go to the Coldshadow Cave.  Find Peevish along with the bottles of Dauntless Draught he stole. He can desert his post if he wants,  but I won't let him take the drinks!", objectives = "Locate \"Peevish\" Paeton Berncort and recover 8 bottles of Dauntless Draught.", progress = "Have you found \"Peevish\" Paeton Berncort and the bottles of Dauntless Draught he took with him?", completion = "I didn't anticipate Peevish would muster the courage to return, but at least you recovered the Draught. \n\nWe'll raise a toast and wish him luck in that cave." }
WordHunterWoW_QuestEN[76171] = { title = "Walking the Path of Tyr", description = "Before they embark on their last training trial, it is a tradition that recruits first receive their Tyr's Guard gear.\n\nThe highest-ranking Tyr's Guard officer would normally do this but... I would be honored if you would bestow their tabard and shield on them for their final trial instead.", objectives = "Distribute gear to the Tyr's Guard.", progress = "The tabard and shield are important symbols of a new recruit's dedication to the Tyr's Guard.", completion = "Thank you, <name>. Now our recruits should be ready for their final trials.\n\nGo to them. I am sure they will want your guidance in completing their missions." }
WordHunterWoW_QuestEN[76176] = { title = "First Steps", description = "Now, let's get to work tracking down the disc. I can't believe that after thousands of years we are so close to seeing Tyr return, much less that I will have a hand in it.\n\nWe should meet with Chromie and Eternus inside. They'll tell us what to do next.", objectives = "Meet Chromie and Eternus in Tyrhold.", completion = "You're back just in time, <name>! We've determined where the Tyr's Guard needs to place the beacons. Check in with Eternus, and we're ready when you are!" }
WordHunterWoW_QuestEN[76194] = { title = "A Grim Portent", description = "Tyrande suspected there was something foul happening here in Felwood... and she was right.\n\nHer priestess, Kaylessa, was sent here to purify the moonwell from the fel corruption that plagues this land, in an effort to reclaim that which belongs to us.\n\nNow we have lost one of our sisters and the moonwell still remains corrupted. We cannot let this stand. We will finish what Kaylessa started, and heal the moonwell. \n\nArko'narin has history with this place. I will let her tell you why we are here.", objectives = "Speak with Arko'narin Starshade to learn about Jaedenar.", progress = "Have you spoken with Arko'narin yet, <class>?", completion = "It is time to put our skills to use, <name>." }
WordHunterWoW_QuestEN[76195] = { title = "Countering Corruption", description = "I cannot thank you enough for your help with this, {name}. I knew I had to be here to help Nari when she told me about this mission. \n\nIt seems as though my skills are needed, just as I thought. The magic here is foul and all-corrupting. It must be contained.\n\nPlease, take this book and read the incantation within after putting the satyr around Jaedenar to rest.\n\nJaedenar need not be a place of death and corruption any longer.", objectives = "Use the Incanter's Tome on 6 Feltouched satyr corpses.", progress = "Please, <name>, you must make sure to cleanse the fel energies that seep from the satyr's corpses.", completion = "These satyr... were Sentinels? Whoever committed this atrocity will pay!" }
WordHunterWoW_QuestEN[76196] = { title = "Mercy or Misery", description = "This place... it was once so important to my family. That is why I agreed to come--and why Lysander wanted to come along as well. \n\n<Arko'narin glances over at Lysander before looking back at you.>\n\nEven after the horrors of Teldrassil, my brother still tries to do everything he can to help others. Much like you, {name}.\n\nCome. We must eliminate the threat that these power hungry cretins pose. I think you are just the kaldorei for the job.", objectives = "Slay cultists occupying Jaedenar in Felwood.", completion = "Good work, <name>." }
WordHunterWoW_QuestEN[76197] = { title = "A Glimpse of Terror", description = "We will strike together on your command, {name}.\n\n<Maiev rolls her shoulders.>\n\nThe last thing this fiend will see is our blades.", objectives = "Defeat Cultist Nethus.", progress = "We must see this through, <name>.", completion = "Our Sentinels... warped and twisted! This will not stand. We will hunt down the leader of this foul incursion, and I will have his head!" }
WordHunterWoW_QuestEN[76201] = { title = "Clone Ownership Verification [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[76203] = { title = "Stepping into the Shadows", description = "Their ranks have been thinned, and their corpses cleansed. You have done well.\n\n<Maiev shifts her weight, looking towards the path leading into Shadow Hold.>\n\nCome, {name}. We must find what lurks below and put an end to it.", objectives = "Navigate through Shadow Hold with Maiev Shadowsong, dealing with threats along the way.", progress = "Not now, <name>.", completion = "We no longer need the element of surprise." }
WordHunterWoW_QuestEN[76205] = { title = "Balancing the Scales", description = "The time for subtlety is over. Lord Hel'nurath has made himself known to us... and I will not rest until I see him slain.\n\n<Maiev clenches her teeth.>\n\nReady yourself, {name}. Together we will show these demons why they should fear the kaldorei.", objectives = "Slay enemies throughout Shadow Hold.", progress = "We will not rest until Shadow Hold has been cleansed of this foul corruption!", completion = "I heard their cries from here, <name>. Well done." }
WordHunterWoW_QuestEN[76206] = { title = "Heart of the Issue", description = "I can't believe how much Nari has been through. This perversion of our history, our culture... my family...\n\n<Lysander glances at his sister.>\n\nThese demons came in here from somewhere. I'm certain the source of their invasion lies in the depths of our barrow den. You and I can put a stop to it.\n\nI won't let this place haunt her any longer, {name}.", objectives = "Disrupt 4 Portals to the Twisting Nether in the depths of Shadow Hold.", completion = "Lysander... he is determined, I'll give him that. \n\nAnd brave. \n\nThank you, <name>. Now... it is time to face the leader of all of this." }
WordHunterWoW_QuestEN[76207] = { title = "Wardens' Wrath", description = "Lord Hel'nurath's hubris gave me an opportunity to study what he's doing. I think I found a way to give us an opening to strike.\n\n<Arko'narin glances at her brother.>\n\nI fear this will take a lot out of Lysander. But I know he'll give it everything he has. Perhaps... perhaps my perceptions have been misplaced.\n\nIt is time to put my... our demons to rest.", objectives = "Defend Lysander as he works to disrupt Lord Hel'nurath's ritual.", completion = "Don't worry over me, <name>. My sister does enough of that already.\n\nLook at the moonwell instead. It's beautiful..." }
WordHunterWoW_QuestEN[76212] = { title = "A Mark For A Protector", description = "Traditions should not hold us back, {name}. They should inform the future. \n\n<Maiev looks at Lysander before turning her gaze back to you.>\n\nI have let my perceptions hold me back as well. No more. I am tired of seeing rifts between our people, regardless of what they use to better themselves or the world.\n\nIt is time I give Lysander his marking. The kaldorei are no strangers to change. Our traditions should adapt to our lives, not define them.", objectives = "Observe Lysander's facial marking ceremony.", completion = "I can't believe it, <name>! I can't believe it!\n\nHow... why...? Today will go with me for all of eternity. Thank you." }
WordHunterWoW_QuestEN[76213] = { title = "Honor of the Goddess", description = "Today is a day of celebration, {name}. And a day of new beginnings. \n\nArko'narin and Lysander have reminded me that the kaldorei are no strangers to change. I forget, sometimes, how long I was away, and just how much my kin have progressed in my absence. \n\n<Maiev looks up to the sky.>\n\nLysander celebrates this day, but your service also deserves to be recognized. Come, {name}.", objectives = "Learn the meaning of Ama'shan from Maiev Shadowsong.", completion = "Hold your head high, Ama'shan <name>.\n\nMay your deeds continue to inspire the kaldorei." }
WordHunterWoW_QuestEN[76214] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "Focus on the photographer and follow their directions.", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, <name>. \n\nYou are one stylish <class>." }
WordHunterWoW_QuestEN[76217] = { title = "Living History", description = "My name is Nirobin. It is worth remembering, as I am a genius in the field of arcane codicology! Quite an accolade, if I say so myself... and I do say so!\n\nI've spent countless hours fusing blue and bronze dragon magic to investigate history like never before. Today, you and I will experience the results of my effort!\n\nLet's start by using my instruments on a fabulously preserved goblet uncovered from the Forbidden Reach.", objectives = "Activate Nirobin's instruments to analyze the Intriguing Dracthyr Goblet.", progress = "You may be frightened.\n\nTry to dig deep inside of yourself for strength... if only because there's nothing I, personally, can do to help you with that.", completion = "Unexpected...\n\nBut \"unexpected\" is the exact territory pioneers like myself were born to explore! \n\nOnward! For scholarship!" }
WordHunterWoW_QuestEN[76241] = { title = "Lab Partners with a Squirrel", description = "I have finally brought history itself to life! I am a success!\n\nNow let's utilize your particular set of skills. Chiefly, I require your ability to go outside without dying of fright.\n\nChanneling my magic onto our new friend here, I'll teleport it to the location with the highest concentration of resonant energy linked to the relic. You'll meet up with it there and await further instructions.\n\nFear not! My magics may elude your understanding, but my intellect is certain to guide us true!", objectives = "Meet Reese at the Lost Atheneum in the Forbidden Reach to continue your research.", completion = "<Out of this arcane squirrel's mouth comes the crackled sound of Nirobin's voice.>\n\n<name>? Can you hear me? It's Nirobin! Codicological genius and mild agoraphobe!\n\nI assume you're ready to use this critter to uncover the lost secrets of Dracthyr civilization. Why else would you be talking to a squirrel?" }
WordHunterWoW_QuestEN[76242] = { title = "A Research Thesis Worth Publishing", description = "Reese here is hungry as a dragon-horse for clues. Clues of the past!\n\nMore specifically, we're going to use my unique brand of magic to unveil and analyze energy that resonates with the same frequency as our relic. \n\nYou will guide Reese to these \"clues,\" where I will use him as a remote conduit to absorb those energies. \n\nWhen we've reached our critter's capacity to hold those energies, I'll port him back here to transmute it all into cold, hard data.\n\n<Reese winks at you. How strange...>", objectives = "Ingest clues in the Lost Atheneum with Reese.", progress = "You'd think I'd know about the history of the Forbidden Reach, considering I was there for thousands of years.\n\nBut surprise! I wasn't much for the world outside of my lab back then.", completion = "I am completely baffled and mildly impressed that you showed no outward embarrassment while escorting a flying, translucent blue squirrel in the open like that. Quite commendable! Bravo!\n\nFor now, accept this reward. If you find it lacking, please write to the academy about my annual stipend.\n\nFor later, be prepared for further codicological excursions on my behalf!" }
WordHunterWoW_QuestEN[76244] = { title = "Prince in Peril", description = "I was fighting off a pack of vicious gnolls who were threatening my prince when there was a flash of light. Suddenly, I was in this strange place and the prince was gone! It must have been that dastardly Matriarch Bluepelt.\n\nPlease, find Prince Wrynn and give those gnolls what for!", objectives = "Defeat time-lost gnolls and recover the missing Llane Wrynn.", progress = "Did you find him?", completion = "Thank you. The prince has returned safely." }
WordHunterWoW_QuestEN[76246] = { title = "Manastorm Mystique", description = "The Manastorms are... unique. \n\nWhile their romance can be explosive, the spark that fanned that flame was quite small. Oddly, Millhouse is having an uncharacteristic crisis of confidence. \n\nWe need you to help bring them together. May the titans have mercy on us all...", objectives = "Talk to Millhouse Manastorm in Dalaran.", progress = "The chaos these two will cause concerns me greatly. However, the timeline must be maintained.", completion = "You kept events as they should be, and helped two people find love.\n\nThat is good. We should focus on the positives here. Not on the mayhem they will cause in the future." }
WordHunterWoW_QuestEN[76247] = { title = "Keep the Home Fires Burning", description = "The keyflame braziers, located across the countryside keep the darkness at bay and our people safe. Many have gone dark as the Radiant Remnants needed to maintain them have become harder to find.\n\nWe've worked hard to ensure our brazier is always lit, but we could always use your help.\n\nPlease gather remnants from our supplies and use them to help empower our family keyflame.", objectives = "5 Hillhelm Remnant Supplies gathered and used to empower the Hillhelm Keyflame.", progress = "Have you empowered our keyflame?", completion = "The warmth of the flame already gives hope that we can retake these lands. Please take a few of these spare remnants to help light the other nearby keyflames." }
WordHunterWoW_QuestEN[76251] = { title = "Fowl Beasts", description = "I believe my time displacement was caused by the horrific creatures to the south.\n\nI can hear them even now, with their monstrous noises. No doubt they ripped me from my original time just to taunt me.\n\nSlay them for me and for the safety of all good people in this world.", objectives = "Slay 10 Fowl Beasts in Winterpelt Hollow in Azure Span.", progress = "Well? What are you waiting for? Think of all the children you could be saving from those monstrous creatures.\n\nNot that I saw any, but you never know.", completion = "You have done this world a service.\n\n<Nathanos shudders.>\n\nNo one should have to see such creatures in their lifetime. I can still hear their quacking now..." }
WordHunterWoW_QuestEN[76257] = { title = "Darkmaster's Scourgestone", description = "<The scourgestone in your hand feels as real as everything else in this memory. It chills your very bones as it rests in the palm of your hand.\n\nWhile it may be a relic of a past time, the Argent Dawn should nonetheless be made aware of its existence.\n\nThe ritual conducted upon Eva's journal may have had greater consequences than either of you anticipated.>", objectives = "Find somebody interested in the Darkmaster's Scourgestone.", completion = "A scourgestone? I don't understand. How did you ever find this? After all we have done, here and upon Northrend...\n\nNo, it does not matter. I will take it off your hands and ensure its destruction, <name>. Surely this is one of the last in existence. Surely.\n\nIf it happens that you find others like this, bring them to me as well. I hope for all our sakes this is the last we ever speak of this." }
WordHunterWoW_QuestEN[76258] = { title = "By Time Fire be Purged!", description = "That big ol' slag elemental has taken the heart of me forge! Without it, a timeforge is just, well, a forge. And that's no use to a chronosmith!\n\nEven if we had Seashellamayne, I wouldn't be able to repair it.\n\nSuch power cannot be allowed to remain in the possession of that... that molten moron!\n\nThe other elementals took off for the towers. I bet half me beard the big one's close by too.", objectives = "Retrieve the Heart of the Timeforge.", progress = "Those confounded elementals must have come from the heart of me forge. Was it destabilized, somehow?\n\nEither way, it's bad news. Every chronosmith worth their minute knows you don't mix elemental and temporal energies.", completion = "<Ironus clutches his chest in relief with a beaming smile.>\n\nThat was a close call! Can you imagine Eon's Fringe burning down shortly after I arrive? How embarrassing.\n\nAnd look at that, one of those wee elementals from me forge seems to have taken a liking to you! You're free to keep it.\n\nIn fact, I insist. Keep it. I don't want it." }
WordHunterWoW_QuestEN[76263] = { title = "The Dread Citadel - Naxxramas", description = "Long ago, magical wards placed upon Naxxramas stymied our attempts to assault Kel'Thuzad's forces. Though I was able to conceal our army past them, I have since learned to dispel them should the need ever arise.\n\nI will confess my disbelief of your story. However, if you are so devoted to this investigation, I will enchant your insignia so you may breach these barriers yourself. For a price.", objectives = "Archmage Angela Dosantos in the Eastern Plaguelands wants 5 Arcane Crystals, 6 Large Brilliant Shards, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn.", progress = "Have you brought the necessary reagents?", completion = "You will feel a slight tingle, <name>. That sensation means it's working. Once complete, you should be able to see whatever it is you believe you will find." }
WordHunterWoW_QuestEN[76264] = { title = "The Dread Citadel - Naxxramas", description = "Long ago, magical wards placed upon Naxxramas stymied our attempts to assault Kel'Thuzad's forces. Though I was able to conceal our army past them, I have since learned to dispel them should the need ever arise.\n\nI will confess my disbelief of your story. However, if you are so devoted to this investigation, I will enchant your insignia so you may breach these barriers yourself. For a small fee.", objectives = "Archmage Angela Dosantos in the Eastern Plaguelands wants 2 Arcane Crystals, 3 Large Brilliant Shards, and 30 gold pieces. You must also be Revered with the Argent Dawn.", progress = "Have you brought the necessary reagents?", completion = "You will feel a slight tingle, <name>. That sensation means it's working. Once complete, you should be able to see whatever it is you believe you will find." }
WordHunterWoW_QuestEN[76265] = { title = "The Dread Citadel - Naxxramas", description = "Long ago, magical wards placed upon Naxxramas stymied our attempts to assault Kel'Thuzad's forces. Though I was able to conceal our army past them, I have since learned to dispel them should the need ever arise.\n\nI will confess my disbelief of your story. However, if you are so devoted to this investigation, I will enchant your insignia so  you may breach these barriers yourself.", objectives = "Archmage Angela Dosantos in the Eastern Plaguelands will empower your Argent Dawn Commission at no cost. You must be Exalted with the Argent Dawn.", completion = "You will feel a slight tingle, <name>. That sensation means it's working. Once complete, you should be able to see whatever it is you believe you will find." }
WordHunterWoW_QuestEN[76266] = { title = "A Multitude of Tasks", description = "Hi {name}! I have a super exciting assignment for today. I need you to place seven loaves of bread around Stormwind, and five jugs of milk in Orgrimmar. You'll finish that up with...\n\n<Chromie looks at a note in her hand.>\n\nSeven hundred and forty two grains of rice scattered across Pandaria!", objectives = "Perform a series of tasks in the Everywhere Inn in Eon's Fringe.", progress = "You're so lucky, always getting to do these fun quests! Meanwhile I'm stuck here, just telling people what to do.", completion = "Wow, that was incredible! The three day journey with the Emperor of Pandaria and his band of heroes was really the highlight.\n\nThanks for letting me stretch my wings, <name>. I'll take it from here." }
WordHunterWoW_QuestEN[76268] = { title = "Corruptor's Scourgestones", description = "", objectives = "A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", progress = "A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", completion = "More and more scourgestones pile up by the day, <name>, from yourself and a growing number of other adventurers.\n\nFortunately, none of our soldiers have mysteriously disappeared nor have I heard more bloodcurdling screams than what is normal for this region.\n\nI would rather not ask questions. Here is your reward." }
WordHunterWoW_QuestEN[76269] = { title = "A Mislaid Egg", description = "Oh dear, this is a tricky one. We need you to relocate an egg to somewhere that Rhonin will be certain to notice it. It may sound odd, but his discovery of that egg sets into motion the events that will free Alexstrasza from the Old Horde--and save the egg, too!\n\nWe're sending you to Dun Algaz. It's not where any of this should be taking place, but time is like cheese right now. Tasty and full of holes.\n\nOh, and here's some sand. It'll help you be a bit more stealthy.", objectives = "Find the Red Dragon Egg and place it someplace conspicuous.", progress = "Did you find a good spot for the egg?", completion = "Did you get it in the right spot? What am I saying--of course you did, or we wouldn't be here! \n\nWhen Alexstrasza was freed, it secured a victory at the Battle of Grim Batol. More importantly, she and the other Aspects forced Deathwing to beat a hasty retreat. If Rhonin hadn't located her, who knows what Deathwing would've accomplished?\n\n<Chromie lowers her voice, glancing at Alexstrasza.>\n\nShe arrived just after you left--like she knew what we were doing!" }
WordHunterWoW_QuestEN[76270] = { title = "Invader's Scourgestones", description = "", objectives = "An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", progress = "An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", completion = "More and more scourgestones pile up by the day, <name>, from yourself and a growing number of other adventurers.\n\nFortunately, none of our soldiers have mysteriously disappeared nor have I heard more bloodcurdling screams than what is normal for this region.\n\nI would rather not ask questions. Here is your reward." }
WordHunterWoW_QuestEN[76271] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "Focus on the photographer and follow their directions.", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, <name>. \n\nYou are one stylish <class>." }
WordHunterWoW_QuestEN[76272] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!.", objectives = "Focus on the photographer and follow their directions.", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, <name>. \n\nYou are one stylish <class>." }
