WordHunterWoW_QuestEN[76290] = { title = "Omarion's Second Handbook", description = "Wilhelm,\n\nIf you are reading this, the first adventurer I sent to you has perished. As have I, finally. I want you to know that my dying thoughts revolved around you and your ineptitude in tradeskills.\n\nAbout the book: These are the rest of my recipes. Please share them with someone more capable. Alas, I am sure you will keep them for yourself and charge a hefty fee for your services because you are, after all, a bastard.\n\nIn Disdain,\nOmarion", objectives = "Return the handbook to Master Craftsman Omarion at Light's Hope Chapel in the Eastern Plaguelands.", completion = "Ah. My book of recipes, sans all the recipes.\n\n<Omarion opens the book, flips its single page, and promptly closes it again.>\n\nI hope you're interested in learning how to stitch cloaks." }
WordHunterWoW_QuestEN[76308] = { title = "The Trial of Style", description = "Well, that's certainly an... interesting look, {class}.\n\nMe? Judgmental? Certainly not. However, I'm curious what others would think of it.\n\nYou should speak to the Transmogrifier over there and enter the Trial of Style.\n\nWe'll see what public opinion says about your choice in garb.", objectives = "Speak to a Transmogrifier to enter and complete the Trial of Style.", progress = "Ugh, I'm so bored.\n\nDid you complete the Trial of Style yet?", completion = "That's mildly impressive.\n\nMildly.\n\nOff with you now. I'm tired of looking at you." }
WordHunterWoW_QuestEN[76309] = { title = "Gilneas Gambit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76310] = { title = "Gilneas Gambit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76311] = { title = "Gilneas Gambit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76317] = { title = "Call of the Dream", description = "A great tree grows within the Dream. Soon, it will emerge in Azeroth.\n\nBut before it does, we must protect it from Fyrakk's forces. We must band together and see it through its verdant birth.\n\nJoin me and the others in the Ancient Bough. Together, we will travel into the Emerald Dream.", objectives = "Meet Merithra within the Ancient Bough in the Ohn'ahran Plains.", completion = "Not so long ago, the World Tree was planted within the Emerald Dream. There, we have kept it safe.\n\nNow our enemies have found their own way into the Dream. We must unite and protect it. The tree has so much promise... and potential." }
WordHunterWoW_QuestEN[76318] = { title = "Emerald Welcome", description = "We protected the tree by guarding all entrances to the Emerald Dream. Now Fyrakk has found allies to open the way for him.\n\nI will do the same for you and our allies. The green dragonflight cannot do this alone.\n\nThrough this portal, we will enter the Dream together. We must protect that realm and all that grows within it.", objectives = "Enter the Emerald Dream through the portal in Ancient Bough.", progress = "There is much to be done.", completion = "Fyrakk's power threatens the fabric of the Dream. We must hurry to save the realm. This drake will aid you." }
WordHunterWoW_QuestEN[76319] = { title = "Feast or Flaming", description = "Already Fyrakk damages the fabric of the Dream. I can feel it burning, as if flames were consuming my scales.\n\nAnd I know that simmering agony is only a fraction of what my son felt when Fyrakk tormented him. \n\nBut we have a potent weapon against this fire. Our faerie drakes and dragons consume what does not belong here. They are excellent allies, if a bit difficult to manage.\n\nNow they need our help. Use this. Clear the skies of encroaching flame.", objectives = "Dragonride or ride the Faerie Drake to consume fiery patches in the Dream.", progress = "The Dream is my home and the home of my flight. I will not let it fall to fire.", completion = "Fyrakk may attack the tree at any moment. We will need the help of the other Wild Gods." }
WordHunterWoW_QuestEN[76320] = { title = "Wild Gods in Our Midst", description = "The Emerald Dream is the home of nature's Wild Gods. We will need their strength and their power to counteract the damage that Fyrakk has brought to this realm.\n\nThe first to seek out is Goldrinn. The ancient wolf has a fondness for Azeroth and mortals, so he is sure to aid us.\n\nOthers may need more convincing. \n\nI will meet you nearby in the Fields of Reverie, where dryads and keepers reside.", objectives = "Seek out Wild Gods and allies within the Emerald Dream.", completion = "We are too late. Fyrakk's forces have already begun their attack on the Dream!" }
WordHunterWoW_QuestEN[76321] = { title = "Burning Assault", description = "The Druids of the Flame are opening a way into the Dream for Fyrakk's forces. Every moment, more of them enter.\n\nWe must stop this rising tide before it becomes a flood.", objectives = "Slay Primalists, Djaradin, and Druids of the Flame.", progress = "Fyrakk's forces must be cut down before they can establish a hold on the Dream.", completion = "You fought well, though I fear there is no stopping these forces now. They may forever reshape the Dream." }
WordHunterWoW_QuestEN[76322] = { title = "The Face of Our Enemies", description = "Powerful foes lurk among the enemies Fyrakk summoned into the Emerald Dream.\n\nI have not seen Cassaphine since she came up out of the barrows. \n\nFind her, and assist our allies by striking down these leaders.", objectives = "Defeat Fyrakk's powerful lieutenants and secure the battlefield.", progress = "It saddens me to see the children of the Dream so twisted.", completion = "This is far worse than I thought. Every time we close a portal, Druids of the Flame open more.\n\nI fear greater dangers are waiting to come through." }
WordHunterWoW_QuestEN[76323] = { title = "Amirdrassil", description = "This tree has grown peacefully in the Emerald Dream since it was planted here. We have watched over it and nurtured it.\n\nAnd now, just when it is about to leave the cradle of this realm and enter Azeroth, our enemies see it as a means to further their own plans.\n\nIt is so much more.\n\nCome. Let us go to Amirdrassil.", objectives = "Meet Merithra at the base of Amirdrassil.", completion = "We arrived just in time. We must intercept Cassaphine before she can do any harm to the tree... or to us." }
WordHunterWoW_QuestEN[76324] = { title = "Lost to the Flame", description = "The Druids of the Flame pose more of a threat than I realized. Not only do they let Fyrakk and his forces pour into the Dream, but they also tempt the Dream's denizens to the flame!\n\nWe cannot dwell on how this happened. It pains me greatly, but Elder Cassaphine must be stopped. \n\nGo with Tyrande and... end the dryad.", objectives = "Defeat Elder Cassaphine at the base of Amirdrassil.", completion = "The Emerald Dream is a place of wild nature, magic, and life.\n\nIt saddens me to see one of ours come to this end. I hope that she is not the first of many.\n\nWait... do you hear that?" }
WordHunterWoW_QuestEN[76325] = { title = "Between Fyrakk and a Hard Place", description = "I hear approaching wings and smell shadowflame.\n\nFyrakk is here.\n\n<Merithra's anger is quiet but terrible.>\n\nGerithus' pain will not go unanswered.", objectives = "Speak to Merithra and prepare for Fyrakk's attack.", completion = "He left the tree alone?\n\nDoes he have another objective?\n\nAnd why is he listening to that Druid of the Flame?" }
WordHunterWoW_QuestEN[76326] = { title = "Home in the Dream", description = "Fyrakk has withdrawn from Amirdrassil, but that only increases my concern. He must have another target within the Emerald Dream.\n\nWe must convene with the others at the base of the tree. Tyrande and the kaldorei have established a camp. \n\nI need to speak with Alexstrasza to determine our next step.", objectives = "Meet Merithra at the central encampment beneath Amirdrassil.", completion = "Now that we have a moment to breathe, we can begin to think about what we will do next.\n\nAnd I know that we are stronger with you on our side." }
WordHunterWoW_QuestEN[76327] = { title = "Eye of Ysera", description = "Galenori's report is deeply troubling.\n\nThe Eye's temple is my seat of power here in the Dream. From it, I commune with the Eye's energies and monitor the health of the Dream and its denizens. The Eye's power flows throughout the Dream, and helps Amirdrassil grow.\n\nIf the djaradin take control of it, they could pervert its nature and stunt the growth of the tree.\n\nMy daughter knows the Eye's importance. I will follow her lead--and so should you.", objectives = "Take the portal from Amirdrassil into the Eye of Ysera.", completion = "So, this is Igira's new general? I am not impressed. We will prevail over this monster." }
WordHunterWoW_QuestEN[76328] = { title = "A New Brute", description = "Galok is but another one of Fyrakk's minions. I will not be baited by his bluster.\n\nThe fire orb must be his doing. Its magic threatens to overwhelm the Eye. Ysera is channeling a shield from inside the temple, but it doesn't seem to be as effective as we expected.\n\nNow, I must confront Galok. Use my magic to bolster our casters if they weaken. The defense must not fall!", objectives = "Use The Dreamer's Essence on 5 Emerald Preservers. Then, meet Ysera inside the temple in the Eye of Ysera.", progress = "With haste, <name>! Our defenders are in pain.", completion = "Mother is struggling..." }
WordHunterWoW_QuestEN[76329] = { title = "In and Out Scout", description = "Bodwin reports that Galok is not the only new threat to the Eye. The djaradin forces below are led by two others--a warrior and a mage.\n\nIt is unwise to engage them directly in their own, well-established base. But I am certain they are a part of Galok's plan of attack.\n\nPlease gather more information from these djaradin leaders. We need to know how best to counteract their attacks.  Bodwin can grant you stealth so that you may move unseen in the camp.", objectives = "Spy on the djaradin leaders in Slagfell Hold.", progress = "What have you seen?", completion = "<Merithra is very still. Only her eyes betray unspeakable rage.>\n\nWe will avenge our kin." }
WordHunterWoW_QuestEN[76330] = { title = "Disarm Specialist", description = "Bodwin's scouting sortie returned more key information. The djaradin plan to use suffused weapons to turn the tide of the battle.\n\nWe must dispatch their smiths and destroy their weapons. Targeting both will weaken and slow them. Then we will have time to consider our next move.\n\nYou will be in great danger on this mission. Take this. \n\nThrowing it onto enemies will temporarily put them to sleep. Use it so that you may avoid becoming overwhelmed in combat.\n\nGood luck, {name}.", objectives = "Kill 6 Suffusion Shapers and destroy 8 Suffused Supplies.", progress = "Tread carefully, <name>. Igira will have your head if you are caught.", completion = "That will hamper their forces significantly." }
WordHunterWoW_QuestEN[76331] = { title = "Merithra's Gambit", description = "We are ready as we can be. Our guard is in place, and our trap ripe to spring.\n\nThe emerald preservers' magic is linked to Ysera's. Upon your signal, they will simultaneously drop the magical defense. This is what Galok's been waiting for. His forces will swoop in like carrion birds.\n\nWe await your word, {name}.", objectives = "Tell Ysera to drop the magical defense.", progress = "Here we go.", completion = "I must trust her--and myself. It is time to fight." }
WordHunterWoW_QuestEN[76332] = { title = "Putting Roots Down", description = "Our trap is many-layered.\n\nPlant these seeds around town. Our gardeners have already prepared the soil. These plants will be effective tools to poisoning our enemy. Handle them carefully, for some may sprout sooner than later.\n\nAlso, Kiya Featherpaw, our umbraclaw keeper, has an idea to mobilize the very strong creatures. Go speak with her.\n\nFinally, meet with Somnikus to give everyone the signal that battle is imminent.", objectives = "Plant seeds in 8 Tilled Soil and speak to Kiya Featherpaw. Then, speak with Somnikus.", progress = "Our trap will work, I know it.\n\nMake haste, <name>. Even with my mother's and my strength...It is like some part of her is holding back her attunement. I dare not dwell on it.", completion = "Now... we are ready." }
WordHunterWoW_QuestEN[76333] = { title = "Triple Threat", description = "Galok is here. All is going according to plan then.\n\nWe will put an end to him and any of his lieutenants.", objectives = "Slay Galok Wingslicer and his djaradin lieutenants The Anvil and Moltenbinder.", progress = "We may have the stronger ground, but don't underestimate any of them.", completion = "We almost have Galok routed. Keep up the pressure!" }
WordHunterWoW_QuestEN[76334] = { title = "Good Counsel", description = "Galok is a coward. He refuses to engage us directly until he is sure of success.\n\nWe do not have the resources to attack his base. But if we cannot go to him, maybe we can entangle him in our own territory.\n\nI am confident we can prepare a trap here for Galok and his forces. My plan is not without risks, and controlling the playing field will be our key advantage.\n\nThe question remains... how do we lure them here?", objectives = "Discuss Merithra's plan with the green dragonflight.", progress = "I must understand everyone's perspectives, especially for a maneuver this big.", completion = "<Merithra solemnly nods at our allies.>\n\nThat settles it then. Let us begin preparations." }
WordHunterWoW_QuestEN[76335] = { title = "Might of the Forest", description = "Use the traps you have laid to your advantage, {name}. Defeat every monster that dares threaten us!", objectives = "Eliminate the djaradin threat in the Eye of Ysera. Activate traps to help you in battle.", progress = "We must protect the Dream!", completion = "The tides are turning! Push the advantage." }
WordHunterWoW_QuestEN[76336] = { title = "Flight and Fight", description = "We have secured the land beneath our feet... now for the skies.\n\nGalok flies from us, but he is weakened. The time to strike is now.", objectives = "Slay 25 Fireswarm Shalewings flying above the Eye of Ysera by striking them with your dragonriding mount.", completion = "It is done." }
WordHunterWoW_QuestEN[76337] = { title = "The Ember Still Smolders", description = "I... almost cannot believe this worked. I am ever grateful for everyone's trust and faith. We could not have won this battle without the help of our allies and the flight.\n\nBut the fight is far from over. Based on the intel we have gathered, Fyrakk and his minions are preparing an even greater assault. Their bases stand strong and terrifyingly close to the Dream's Hope, bastion of Amirdrassil.\n\nThe Eye might have only been a distraction. We will regroup at Amirdrassil with the rest of our allies.", objectives = "Regroup with Merithra at Amirdrassil.", completion = "Thank you for coming, <name>." }
WordHunterWoW_QuestEN[76338] = { title = "A Better Cabbage Smacker", description = "", objectives = "" }
WordHunterWoW_QuestEN[76339] = { title = "Loch Modan Loop", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76340] = { title = "Loch Modan Loop - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76341] = { title = "Loch Modan Loop - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76342] = { title = "Light 'Em Up!", description = "After Vyranoth left, Fyrakk put all four of the Claws of Vyranoth on different tasks.\n\nHe left me in charge of this camp and told me to keep the portals open at all costs. The Druids of the Flame are empowering the portals for the Primalist's reinforcements to come through. \n\nWe should close those portals and thin out their ranks.", objectives = "Weaken the Primalist encampment in the Primalist Stronghold.", progress = "The Primalists will only multiply in numbers if we do not hinder them.", completion = "Disrupting their forces should protect the Dream for now." }
WordHunterWoW_QuestEN[76343] = { title = "Best Laid Plans", description = "Fyrakk may be brash, but he is not a fool. If we are to save the Dream, we must undermine his plans as quickly as possible.\n\nAt their core, the Primalists are unorganized. Infiltrate their camp and search for any clues or information.\n\nThe more information we have, the sooner we can take down Fyrakk once and for all.", objectives = "Collect 4 clues in the Primalist Stronghold.", completion = "Lethka left those notes?" }
WordHunterWoW_QuestEN[76344] = { title = "Primalist Directive", description = "Terro was another one of Vyranoth's claws. He never wanted to attack the Dream, and some of the Primalists who served him may feel the same. See if you can convince them to join our side. \n\nI can put a mark of Vyranoth on you so Terro's troops will not attack you... right away.", objectives = "Convince 5 of Terro's Primalists to side with Vyranoth.", progress = "Terro never wanted to attack the Dream. It was against his nature.", completion = "Terro was always protective of those he commanded. He would have wanted us to save who we can." }
WordHunterWoW_QuestEN[76345] = { title = "Finding Terro", description = "I had no idea my old guard would be willing to return to my side. I am... I am happy to see them. When I chose to go to Alexstrasza, I told no one. I simply left.\n\nBut we must learn more about Fyrakk's plan before pursuing personal matters. Let us see what else Buri can tell us.", objectives = "Uncover more information about Fyrakk's plan in the Emerald Dream.", progress = "If we could just find the other Claws...", completion = "Vyranoth will not rest until Terro is avenged." }
WordHunterWoW_QuestEN[76347] = { title = "Power, Eruption, and Lies", description = "Buri told me that Lethka plans to ignite Cinder Summit, and Vyranoth pursued her.\n\nLethka revealed herself because she knew that Vyranoth would go after her. The power in Cinder Summit can destroy this barrier, or Vyranoth.\n\nWe have to go after them.", objectives = "Slay Lethka at Cinder Summit.", completion = "I cannot celebrate the loss of a friend, but it had to be done." }
WordHunterWoW_QuestEN[76348] = { title = "Big Bright Beautiful Barrier", description = "Buri? Vyranoth?\n\nOnce she left us at the mercy of Fyrakk, we had no choice but to follow him. I do not know what his plan is, but he ordered me and these Primalists to bring down this barrier.\n\nWe have made little progress, but Vyranoth will want us to slow him down.\n\nSome fragments of the barrier have chipped away. If you collect them, we can channel their energy back into the shield.\n\nCan I trust you to undo the damage that I have done?", objectives = "Collect 6 Barrier Fragments in the Emerald Dream.", completion = "Thank you for preventing his onslaught." }
WordHunterWoW_QuestEN[76350] = { title = "The Chronosmith", description = "Are you here to aid us? As you can see, the time anomaly around Eon's Fringe has dissipated and there is no shortage of work to be done.\n\nWe've called in for help from one our best chronosmiths, a bronze dragon by the name of Ironormu. The problem, amongst all this chaos, is that he's nowhere to be found. He should have been back from setting up his workshop by now.\n\n<Tempo sighs in agitation.>\n\nCan you go find him?", objectives = "Seek out Ironormu at the forge in Eon's Fringe.", completion = "As you can see, I'm in a bit of a predicament. Not only is me forge sealed with a timelock, it's filled to the brim with fire elementals!\n\nTo make things worse, young Finduin here is in DIRE need of a talented chronosmith to repair his blade, Seashellamayne. And I can't exactly do much when me forge is...\n\n<Ironus gestures wildly in frustration.>\n\nI'd be mighty appreciative if you could help me out." }
WordHunterWoW_QuestEN[76351] = { title = "Titanic Beasts", description = "<This small device rolled out of the mouth of a beast you defeated.\n\nIt appears to be a titan information device, but it's more compact than devices you've seen on Azeroth.\n\nSoridormi will want to see this.>", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", completion = "<Soridormi turns the device over in her hands.>\n\nYou said this came from the mouth of a large beast?\n\nWell, I hope the end was quick for its last owner.\n\nI'll put it on one of the tables behind me, in case you want to view it later. Maybe it will be cleaner by then." }
WordHunterWoW_QuestEN[76352] = { title = "Chronohammer Time!", description = "If I'm to repair young Finduin's blade here, then we need to crack open this timelock on me forge. And if a hammer can break a lock, then I'm betting a chronohammer can break a timelock.\n\nUnfortunately, my hammer's a wee bit out of sync. But we're in the prime sort of mishap to fix that. Nearby rifts are tearing into our timeline just outside the Temporal Conflux and out-of-time uglies are pouring through.\n\nHead out of Eon's Fringe, clear the area, and recharge my hammer.", objectives = "Kill time-displaced creatures and destroy rifts in the Passage of Time to resync Ironus's Chronohammer.", completion = "You found WHAT coming out those time rifts? Well, that ain't good!\n\nI'll be sure to flag Tempo down and let her know. I shudder to think what would happen if we allowed more of those creatures to run rampant into our timeline.\n\nLooks like you handled them nicely, though. I can feel temporal energies radiating off my hammer from here!" }
WordHunterWoW_QuestEN[76354] = { title = "For the Hoard!", description = "I have a storage vault in the Passage of Time chock-full of chronomatic crates. They contain timelost artifacts from various timelines.\n\nUnfortunately, me safeguard protocols on the vault itself were damaged by those blasted time rifts. I did a quick fly-about and saw those infernal looters scattering my crates everywhere!\n\nSince you're heading that way, can you grab some of my possessions as you go? Not all of them, of course! Just the important stuff.", objectives = "Find and collect Ironus's artifacts.", progress = "I swear by the heat of me forge, if any of those retched looters broke into me crates and took anything, I'm going to...\n\nWell, we bronze dragons have all sorts of techniques, don't we?", completion = "Oh, thank the timeways. You found me stuff!\n\n<Ironus hurriedly examines his possessions.>\n\nTo some these relics may seem like rubbish, but to me? They're all treasures.\n\nOh and don't worry about the rest of the crates. Once these time rifts are dealt with, I'll head on over and get them back in the vault." }
WordHunterWoW_QuestEN[76355] = { title = "If a Hammer Can Break a Lock...", description = "Now that the hammer is all charged up, all we need is to take one big swing at the time-lock and BOOM! Nothing breaks a temporally-crafted anomaly like a temporally-charged hammer.\n\nWe'd just need to account for a possible sundering of time and...\n\n<Ironus hesitates for a moment as he makes a few calculations under his breath before he looks at you with a not-so-confident smile.>\n\nTell you what? You earned this! You do the honors.", objectives = "Shatter the time-lock with the Chronoforged Hammer.", completion = "Well, that certainly went according to plan, didn't it? Shattered without a blip or quiver in time! I had zero doubts.\n\nUnfortunately, it seems those elementals were a wee bit restless and took off  the first chance they got.\n\nOne problem extinguished, a dozen ignited." }
WordHunterWoW_QuestEN[76356] = { title = "Sword Stealing Searers", description = "Those grubby forgespawns knocked Finduin right over and took Seashellamayne! They must've sensed the temporal energies lingering on the sword.\n\nCan't imagine what they'd want with it, but there's no time to wait and see.\n\nEverything you've done won't mean much if I don't have Finduin's blade to fix. Could you fetch it for me? After all, the fate of Azmerloth depends on it!", objectives = "Retrieve Finduin Wryngrrlgulgll's blade Seashellamayne.", progress = "Like time-moths to the chrono-flame, those wee elementals were drawn to Seashellamayne!\n\nI can only hope the damage done to it is minimal.", completion = "Thank the timeways you retrieved Seashellamayne before those fiery creeps could cause lasting damage! The blade is a bit burnt, but nothing I can't hammer out\n\nGlad you're in one piece as well. A few char marks, I see, but nothing you couldn't handle.\n\nWear that soot like the badge of pride it is." }
WordHunterWoW_QuestEN[76357] = { title = "Searing Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[76358] = { title = "Searing Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
