WordHunterWoW_QuestEN[76361] = { title = "Fashion Week", description = "Ah, the Trial of Style is upon us, {class}. \n\nThe outfits, the creativity, the elegance of the Trial are truly a sight to see.\n\nSpeak to a Trial of Style Envoy to learn more about the event.\n\nA word of warning, those envoys can be... challenging to deal with.", objectives = "Speak to a Trial of Style Envoy.", completion = "You really think you're ready for the Trial of Style?\n\nIn that?" }
